(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-moe-prefetch-dual-phase"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-1\">一 · 一次长尾事故：解码步被冷专家拖住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-2\">二 · 它精确针对的问题：动态加载与两相失配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-3\">三 · 预取收益判据：什么时候值得预取</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-4\">四 · 它不解决什么：三条明确的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-5\">五 · 一个具体例子：热度表如何救回一个长尾步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-6\">六 · 预取失效时的带宽反噬与适用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-7\">七 · 调度器入口：相标记与 chunk 切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-8\">八 · 预填相内：直方图统计与热度表生成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-9\">九 · 解码步 t：第 l 层计算与第 l+1 层预取发起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-10\">十 · 第 l+1 层到达：命中路径与回退路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-11\">十一 · 每 N 步重排：热度表更新与槽位淘汰</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-12\">十二 · SLO 逼近：冻结预取深度与尾延迟保护</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-13\">十三 · 预取收益判据与失效边界：每一步的输入、输出与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-14\">十四 · 把单步时间拆成三笔账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-15\">十五 · 推导的关键一步：为什么是取大而不是相加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-16\">十六 · 命中率不是免费的：估计误差怎么进惩罚项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-17\">十七 · 伪代码：把式子落到可实现的循环里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-18\">十八 · 参数档位与退化边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-19\">十九 · 一个数值算例：命中率差 0.2 意味着什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-20\">二十 · 三条判据把&quot;该不该用&quot;钉死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-21\">二十一 · 请求形态：为什么变长对话是这套机制的“原生负载”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-22\">二十二 · 长度分布：预填 chunk 粒度与解码步数的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-23\">二十三 · 并发与批大小：驻留区容量是硬约束，L2 预算是软约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-24\">二十四 · 负载不对时的三种退化形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-25\">二十五 · 负载适配的工程判据：先量分布，再定配方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-26\">二十六 · 负载配方：命中率、批大小与路由稳定性的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-27\">二十七 · 硬件档位：把 L2 预算当作一等资源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-28\">二十八 · 并行拓扑：专家放置与预取域的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-29\">二十九 · 量化方案：驻留区占用与精度损失的联合取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-30\">三十 · KV 策略：按相切换的读取优先级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-31\">三十一 · 调度参数：批大小、chunk 粒度与重排周期</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-32\">三十二 · 可复现的配置思路：从约束反推参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-33\">三十三 · 预取带宽账：HBM 与 L2 的双重挤占</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-34\">三十四 · 命中率衰减曲线：规模上去后先崩的是 h</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-35\">三十五 · 通信耦合：预取与 All-to-All 抢同一条链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-36\">三十六 · 尾延迟的三个放大器：回退、重排、冻结</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-37\">三十七 · 规模上限的判定顺序与容量规划口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-38\">三十八 · 预取预算耗尽时，先崩的是 L2 与 HBM 带宽而不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-39\">三十九 · 精度问题的来源与诊断路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-40\">四十 · OOM 的三条触发链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-41\">四十一 · 批抖动与路由不均的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-42\">四十二 · 尾延迟尖刺的定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-43\">四十三 · 监控指标与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-44\">四十四 · 失败模式与相邻机制的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-45\">四十五 · 失效边界：预取收益判据、SLO 冻结与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-46\">四十六 · 同族谱系：四条路线与它们的判据差异</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-47\">四十七 · 决策表：按场景条件选路线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-48\">四十八 · 命中率阈值：什么时候预取开始亏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-49\">四十九 · 与分离式专家并行的边界划分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-50\">五十 · 量化与驻留区容量对选型的反向约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-51\">五十一 · 选型落地：三个必须先测的量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-prefetch-dual-phase-sec-52\">五十二 · 同族对照：固定驻留、纯按需与双相预取的选型边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:564px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 564.0 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"482.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入调度器，标记为预填相；按 chunk 切分并统计各层路由直方图</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"482.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">预填相结束前，用路由直方图生成解码相专家热度表，写入每层专家缓存槽位</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"482.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码步 t 计算第 l 层时，依据热度表与上一 token 路由对第 l+…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"482.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">第 l+1 层到达时命中驻留专家则直接分组 GEMM，未命中者回退按需加载…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"482.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">每 N 步按命中率与惩罚计数重排热度表，淘汰低收益专家槽位</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"482.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">SLO 逼近时冻结预取深度，优先保障已排队 token 的解码步</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-1\">一 · 一次长尾事故：解码步被冷专家拖住</h3>\n<p>先看一个在线的失败案例。某在线对话服务跑的是专家并行（EP）的 MoE 模型，预填相吞吐达标，但解码相的 TPOT 分位数持续越线。抓取单步时间线后看到的现象很一致：绝大多数解码步的耗时贴着当前层分组 GEMM 的下界走，但每隔若干步会出现一个明显拉长的步——在这一步里，第 <span class=\"inline\">l</span> 层路由把少量 token 打到几个本轮从未被访问过的专家上，这些专家的权重不在 L2，也不在显存驻留区，只能触发一次 HBM 到 SM 的按需搬运。搬运本身要占带宽，更要命的是它与该层 GEMM 串行：GEMM 必须等权重到位才能发射，于是这一层的耗时从“计算受限”退化为“访存受限”，整个解码步被拉长。因为解码是自回归的严格串行链，任何一层的 stall 都无法被后续层掩盖，长尾直接体现在 TPOT 的 P99 上。</p>\n<p>把这件事写成代价模型，单步时间可以表达为</p>\n<div class=\"formula\">$$T_{\\text{step}}=\\sum_{l=1}^{L}\\Big(\\max\\big(T^{\\text{gemm}}_{l},\\ T^{\\text{pref}}_{l+1}\\big)+\\big(1-h_{l}\\big)\\,T^{\\text{miss}}_{l}\\Big),\\quad h_l=\\frac{|E^{\\text{hit}}_l|}{|E^{\\text{route}}_l|}$$</div>\n<p>式中 <span class=\"inline\">h_l</span> 是第 <span class=\"inline\">l</span> 层的专家命中率，<span class=\"inline\">\\(T^{\\text{miss}}_l\\)</span> 是未命中时的回退加载代价。这个式子的关键在于它把两件事分开：<span class=\"inline\">max</span> 项表示预取搬运可以被当前层 GEMM 掩盖的部分，而 <span class=\"inline\">\\((1-h_l)T^{\\text{miss}}_l\\)</span> 是掩盖不掉、直接加到步时间上的惩罚。事故中的服务 <span class=\"inline\">h_l</span> 在多数步接近满值，但在冷专家出现的步上骤降，惩罚项一次性放大，于是均值好看、分位数崩坏。这就是“为什么需要双相专家预取”的原始动机：不是吞吐不够，而是解码链上不可掩盖的访存 stall 无法被批调度或增大批来吸收。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-2\">二 · 它精确针对的问题：动态加载与两相失配</h3>\n<p>这个算法要解决的是两个耦合在一起的具体问题。第一是解码阶段专家权重的动态性：MoE 每层有大量专家，但单个解码步的 token 数少，路由只激活其中一小部分，权重无法全部常驻，只能按路由结果动态加载。冷门专家（长尾路由、领域漂移后的新热点）触发按需搬运，形成不可预测的 stall。第二是预填相与解码相的访存模式根本不同：预填相一次处理成百上千 token，路由直方图接近全局分布，访存是吞吐友好的大块流式；解码相每步只有少量 token，访存是低延迟、小粒度、强依赖前一步结果的串行读取。用同一套缓存淘汰策略同时服务两相，必然在某一相上失配——偏吞吐的策略会让解码相的冷专家反复落空，偏低延迟的策略又会在预填相浪费驻留容量。</p>\n<p>算法的切入点是：把请求生命周期显式切成预填相与解码相，用预填相统计出的路由直方图作为解码相的“先知”，在计算当前层时异步预取下一层的高概率专家。它把“预测”这件事的成本压到几乎为零——直方图本来就在预填的 chunk 计算中顺带产出，不需要额外的前向或离线画像。这一点决定了它与纯按需加载、固定缓存策略的分野：前者完全被动，后者对分布变化无感，而双相预取把预填相已经付出过的计算当作解码相的信息资产，并允许热度表跨请求复用。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-3\">三 · 预取收益判据：什么时候值得预取</h3>\n<p>预取不是免费的。每一个被预取的专家都占用 HBM 带宽与 L2 容量，而这些资源与注意力 KV 读取是竞争关系。因此算法需要一个逐专家的收益判据，决定某个候选专家是否进入预取集合：</p>\n<div class=\"formula\">$$G_e = p_e \\cdot T_{\\text{gemm}} - c_{\\text{prefetch}} - (1-p_e)\\,c_{\\text{miss}}$$</div>\n<p>这里 <span class=\"inline\">p_e</span> 是热度表给出的专家 <span class=\"inline\">e</span> 在下一层被命中的概率，<span class=\"inline\">\\(T_{\\text{gemm}}\\)</span> 是当前层 GEMM 可提供的掩盖窗口，<span class=\"inline\">\\(c_{\\text{prefetch}}\\)</span> 是搬运代价，<span class=\"inline\">\\(c_{\\text{miss}}\\)</span> 是未命中回退惩罚。判据的工程含义很直接：只有当“命中后省下的 stall”减去“搬运成本”再减去“押错时的期望惩罚”仍为正，预取才划算。注意 <span class=\"inline\">G_e</span> 与 <span class=\"inline\">\\(T_{\\text{gemm}}\\)</span> 成正比——批越大、当前层 GEMM 越长，掩盖窗口越宽，可预取的专家就越多；反之在小批、短 GEMM 的场景里，预取窗口窄，激进预取只会把带宽浪费在押错的专家上。这也解释了为什么该算法的批大小要按显存驻留区容量与 L2 预算来设定，而不是单纯追大。</p>\n<p>用伪代码表达单步的决策顺序：解码步 <span class=\"inline\">t</span> 计算第 <span class=\"inline\">l</span> 层时，取热度表与上一 token 的路由分布，对第 <span class=\"inline\">l+1</span> 层的候选专家按 <span class=\"inline\">G_e</span> 排序，对正收益者发起 cp.async 预取到 L2 或显存驻留区；第 <span class=\"inline\">l+1</span> 层到达时，命中者直接进入分组 GEMM，未命中者回退按需加载并累加惩罚计数。整个预取动作与第 <span class=\"inline\">l</span> 层的 GEMM 重叠，这正是公式中 <span class=\"inline\">max</span> 项得以成立的前提。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-4\">四 · 它不解决什么：三条明确的边界</h3>\n<p>把适用边界说清楚，比罗列优点更有工程价值。第一，它不解决路由本身的稳定性问题。热度表是预填相直方图的产物，其有效性建立在“预填分布可代表解码分布”之上。若请求形态是长尾占比高、或者分布快速漂移（例如多轮对话中话题突变、突发流量带来新领域 prompt），热度表的预测力会骤降，<span class=\"inline\">p_e</span> 失真导致 <span class=\"inline\">G_e</span> 大面积转负，命中率下滑，预取反而挤占注意力 KV 读取带宽，整体变慢。此时需要周期性重排热度表，而重排本身有开销，收益收缩甚至为负。</p>\n<p>第二，它不解决容量上限问题。驻留区大小受 L2 容量与 HBM 带宽预算约束，专家数量超过驻留槽位时，淘汰策略只能决定“谁被牺牲”，不能凭空扩容。规模上限是硬约束，算法只能在预算内做取舍。第三，它不解决预填相自身的吞吐问题——预填相偏吞吐的 KV 写入与大块 GEMM 不在它的优化目标内，它只保证预填相顺带产出的直方图足够细（按 chunk 切分以控制统计粒度），以及两相切换时缓存策略能跟着切换。</p>\n<p>还有一个容易被忽略的失败模式：SLO 逼近时冻结预取深度。冻结能保住已排队 token 的解码步不被预取带宽挤占，但冻结策略若过于粗暴，会把本来能掩盖的搬运重新暴露为 stall，放大已排队 token 的尾延迟。这说明该算法的稳定性依赖一个调参正确的冻结阈值，而不是一个无条件的保护开关。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-5\">五 · 一个具体例子：热度表如何救回一个长尾步</h3>\n<p>回到第一节的事故场景。假设第 <span class=\"inline\">l</span> 层 GEMM 的可掩盖窗口 <span class=\"inline\">\\(T_{\\text{gemm}}\\)</span> 足够覆盖一次专家权重的 cp.async 搬运。预填相结束时，直方图显示某几个“冷”专家在近期请求中被路由到的频次虽低但稳定出现，热度表给它们分配了驻留槽位。解码步 <span class=\"inline\">t</span> 计算第 <span class=\"inline\">l</span> 层时，依据上一 token 的路由与热度表，对第 <span class=\"inline\">l+1</span> 层的这几个候选专家发起预取；第 <span class=\"inline\">l+1</span> 层到达时命中，直接分组 GEMM，<span class=\"inline\">\\((1-h_l)T^{\\text{miss}}_l\\)</span> 项为零，该步不再被拉长。反之，若这几个专家未被预取，则重演按需搬运，惩罚项一次性加到步时间上。</p>\n<p>这个例子说明算法的收益不是“平均变快”，而是“把长尾步拉回均值附近”。代价则体现在另一侧：被预取但最终未被路由命中的专家，其搬运带宽白花，且占用的 L2 容量会挤压同层注意力 KV 的读取窗口。因此工程判断的落点是：先确认服务的路由分布是否相对稳定、预填统计能否代表解码分布，再决定预取深度；若长尾请求占比高或分布漂移快，应收缩预取集合、提高重排频率，而不是一味加深预取。规模上限始终由 L2 容量与 HBM 带宽预算封顶，这一点在容量规划阶段就要与批大小、驻留区槽位数一起定。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-6\">六 · 预取失效时的带宽反噬与适用边界</h3>\n<p>先看一个典型的线上失败形态：某在线对话服务在 B200 上跑 MoE 解码，启用双相专家预取后，P99 TPOT 在流量平稳时确实收敛，但在一次话题突变的流量峰值中反而劣化。原因是预填相统计出的路由直方图已不能代表解码分布，热度表把大量槽位给了已冷掉的专家；解码步仍按旧表对下一层发起 cp.async 预取，这些错误预取占满 HBM 带宽与 L2 容量，注意力 KV 读取被挤到后面排队，命中率 $h_l$ 骤降，未命中回退的按需加载与错误预取叠加，形成比纯按需加载更差的尾延迟。这个案例界定了本方法的边界：它优化的是“可预测的专家加载延迟”，而不是“不可预测的专家访问本身”。</p>\n<p>判断一个专家是否值得预取，不能只看热度表概率，而要用收益判据逐专家裁决：</p>\n<div class=\"formula\">$$G_e = p_e \\cdot T_{\\text{gemm}} - c_{\\text{prefetch}} - (1-p_e)\\,c_{\\text{miss}}$$</div>\n<p>只有当 $G_e&gt;0$ 时才应占用预取深度。$T_{\\text{gemm}}$ 是当前层 GEMM 能掩盖的时间，$c_{\\text{prefetch}}$ 是这次搬运占用的带宽与 L2 槽位代价，$c_{\\text{miss}}$ 是回退惩罚。低命中率场景下 $p_e$ 小，第一项缩水而 $c_{\\text{prefetch}}$ 照付，$G_e$ 转负——这正是事故中“预取反而变慢”的算术根源。工程上应把 $G_e$ 作为槽位准入条件，而不是把热度表前 K 名无条件塞满驻留区。</p>\n<p>适用边界可以压成一张判据表。左列是收益成立的条件，右列是对应的失效条件与系统代价：</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>收益成立</th><th>失效与代价</th></tr></thead><tbody><tr><td>路由稳定性</td><td>预填直方图可代表解码分布，$h_l$ 高</td><td>话题漂移、长尾请求占比高，$h_l$ 骤降，重排开销上升</td></tr><tr><td>带宽预算</td><td>预取被当前层 GEMM 完全掩盖</td><td>错误预取挤占 KV 读取带宽，注意力路径 stall</td></tr><tr><td>L2 容量</td><td>驻留槽位与 KV 工作集共存</td><td>槽位膨胀压缩 KV 命中，解码相低延迟读取受损</td></tr><tr><td>SLO 余量</td><td>预取深度可自由伸缩</td><td>逼近 SLO 时冻结预取，已排队 token 尾延迟被放大</td></tr></tbody></table>\n<p>它明确不解决的问题也要说清：对纯稠密模型无效，因为没有路由可预测；对专家数极少、单专家权重可常驻的模型收益有限，因为按需加载本就不构成长尾；对预填相本身的吞吐瓶颈也无直接帮助——预填相只负责产出直方图，其 chunk 切分粒度影响的是统计代表性而非预填速度。规模上限由 L2 容量与 HBM 带宽预算共同约束：驻留区越大，错误预取的带宽反噬越重。因此部署时应把批大小与驻留槽位绑定在 L2 预算内，并以 TPOT 分位数为约束做准入，而不是以平均命中率为唯一指标。</p>\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-7\">七 · 调度器入口：相标记与 chunk 切分</h3>\n<p>请求进入调度器时，第一件事不是分配 KV 页，而是打相标签。调度器为每个请求写入一个相状态位 <code>phase=prefill</code>，并把该请求的 token 序列按 chunk 切分——chunk 长度不是随意定的，它直接决定路由直方图的统计粒度：chunk 太小，每层直方图样本数不足以稳定估计解码相热度；chunk 太大，预填相尾部的直方图迟迟不能收敛，热度表写入被推迟到解码步已经开始之后。工程上把 chunk 长度绑定到该请求的层数与专家并行度，使每个 chunk 覆盖每层至少一次完整的路由采样。此步输入是请求 token 序列与并行拓扑，输出是带相标签的 chunk 队列和每层一个空的直方图累加器（通常放在 SMEM 或寄存器分片里，避免全局原子操作）。代价落在调度侧：相标记本身零开销，但 chunk 切分改变了预填批的组成，预填吞吐会因 chunk 边界处的 GEMM 形状碎片化而轻微下降；同时直方图累加器占用每 SM 的一小块 SMEM，挤占本可用于双缓冲的容量。例子：一个变长对话请求带 6K token 上下文，切成 4 个 chunk 后，每层在预填相获得 4 次路由采样，足以在预填结束前形成可用的热度排序。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-8\">八 · 预填相内：直方图统计与热度表生成</h3>\n<p>预填相每个 chunk 计算完一层后，路由结果（token 到专家的映射）被就地归约成该层的计数直方图 <code>hist[l][e] += count</code>。这一步与分组 GEMM 共享同一次路由扫描，不额外读一遍 token，因此统计开销近似为零——代价只体现在归约指令占用少量 issue 槽位，以及直方图在 SMEM 中的驻留挤占。预填相结束前，调度器触发一次热度表生成：把每层直方图按专家并行切分归并，除以该层路由 token 总数得到归一化热度 <code>p_e</code>，再按 <code>p_e</code> 降序写入该层专家缓存槽位的元数据（槽位号、专家 id、热度、最近命中计数）。热度表是跨请求复用的：同一模型、同一路由分布下，新请求可以直接继承上一批请求的热度表作为初值，只在本请求预填结束时做一次加权融合。输出是一张每层 M 个槽位的驻留清单，M 由 L2 预算与显存驻留区容量共同决定。代价是显存：驻留区占用本可用于 KV 页的 HBM 容量，M 越大，KV cache 可分配的块数越少，长上下文请求的并发度被压缩；此外热度表元数据本身要落在全局内存并被解码步反复读取，其读取延迟必须被第 <code>l</code> 层 GEMM 掩盖，否则预取决策本身成为 stall 源。例子：某层路由出 64 个专家、驻留区只能放 24 个槽位时，热度表只保留前 24 名，其余 40 个专家在解码相全部走按需加载路径，其惩罚计数从第一个解码步就开始累积。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-9\">九 · 解码步 t：第 l 层计算与第 l+1 层预取发起</h3>\n<p>解码步 <code>t</code> 计算第 <code>l</code> 层时，SM 上正在跑该层的分组 GEMM；与此同时，一个轻量决策线程依据热度表与上一 token 在第 <code>l</code> 层的实际路由，为第 <code>l+1</code> 层挑选候选专家集 <code>E^{cand}_{l+1}</code>，并对每个候选发起 <code>cp.async</code> 搬运到 L2 或驻留区。候选集的选取不是简单取热度前 K，而是按收益判据过滤：</p>\n<div class=\"formula\">$$G_e = p_e \\cdot T_{\\text{gemm}} - c_{\\text{prefetch}} - (1-p_e)\\,c_{\\text{miss}}$$</div>\n<p>只有 <code>G_e &gt; 0</code> 的专家才进入预取队列，这避免了为低概率专家浪费 HBM 带宽。此步输入是热度表、上一 token 路由、当前层 GEMM 的预计时长 <code>T_{\\text{gemm}}</code>；输出是异步搬运句柄与候选集位图。代价有三个方向：其一，<code>cp.async</code> 占用 HBM 读带宽，与同层注意力 KV 的读取直接竞争——KV 读取是解码步的硬实时路径，预取错误会把它挤慢；其二，候选集位图与热度表读取占用 L2 带宽；其三，预取深度（同时 inflight 的搬运数）受 L2 容量约束，深度过大时新预取会驱逐尚未被消费的驻留专家，形成自踩踏。例子：第 <code>l</code> 层 GEMM 预计耗时覆盖一次专家权重搬运的窗口，若 <code>p_e=0.8</code> 且 <code>c_{\\text{prefetch}}</code> 小于 <code>0.8 T_{\\text{gemm}}</code>，该专家进入预取；若 <code>p_e=0.2</code>，判据为负，直接放弃预取，留待按需加载。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-10\">十 · 第 l+1 层到达：命中路径与回退路径</h3>\n<p>第 <code>l+1</code> 层开始计算时，实际路由与预取候选集做一次交集判定。命中者已在驻留区，直接进入分组 GEMM 的专家分组，无需任何搬运等待；未命中者触发按需加载，从 HBM 拉取权重到 SM，这条路径的延迟无法被掩盖，直接计入该步的 stall。回退路径同时更新两个计数器：该专家的惩罚计数 <code>penalty[e] += 1</code>，以及该层的命中率统计 <code>h_l = |E^{hit}_l| / |E^{route}_l|</code>。命中率是后续重排的唯一依据，也是判断预取是否值得继续的直接信号。代价在这里最集中：未命中回退的延迟是解码 TPOT 长尾的主要来源，一个冷专家按需加载可能让该步的 TPOT 跳到数倍于稳态值；而回退路径与命中路径共享同一分组 GEMM 的 barrier，未命中的分组必须等权重到位才能发射，命中分组被迫空转等待，形成同层内的相互拖累。例子：某步路由到 8 个专家，预取命中 6 个，剩下 2 个走回退；这 2 个专家的加载延迟虽然只占该层 GEMM 的一小部分，但由于分组 GEMM 的同步语义，整个第 <code>l+1</code> 层的发射被推迟，TPOT 分位数在此时段明显抬升。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-11\">十一 · 每 N 步重排：热度表更新与槽位淘汰</h3>\n<p>每 <code>N</code> 个解码步执行一次重排。输入是累计命中率、各专家惩罚计数、以及最近 <code>N</code> 步的实际路由分布；输出是新的槽位分配。重排逻辑是：对每个槽位计算其收益估计，收益低的槽位被淘汰，腾出的槽位分配给惩罚计数高且近期路由频繁的专家。重排不是全量重建，而是增量置换——只动收益排序发生交叉的槽位，避免每次重排都刷新整张表带来的元数据写放大。代价是重排期间预取决策短暂失准：新槽位尚未完成首次搬运，旧槽位被驱逐后其专家立刻转为未命中，命中率在重排后的若干步内出现凹陷。这个凹陷的深度取决于 <code>N</code> 的选取——<code>N</code> 太小，重排开销与命中率凹陷频繁出现；<code>N</code> 太大，分布漂移不能被及时跟踪，惩罚计数积累到不可逆的程度。例子：路由分布因对话主题切换而偏移，某批此前冷门的专家在连续若干步被高频路由，惩罚计数快速上升，重排把它们换入驻留区，代价是同一轮被换出的专家在接下来几步全部走回退路径，TPOT 出现一次短促的尖峰。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-12\">十二 · SLO 逼近：冻结预取深度与尾延迟保护</h3>\n<p>调度器持续监控已排队 token 的 TPOT 分位数与 SLO 约束的余量。当余量收缩到阈值以下，进入冻结态：预取深度被压到最低档，只保留收益判据最强的少数候选，把 HBM 带宽与 L2 容量优先让给已排队 token 的解码步与注意力 KV 读取。冻结的输入是 SLO 余量、队列深度、当前命中率；输出是新的预取深度上限与候选集规模。代价是预取收益被主动放弃：冻结期间冷专家回退概率上升，单步 TPOT 的方差变大，但因为带宽不再被预取挤占，KV 读取的确定性提高，尾延迟反而收敛。冻结策略的关键在于退出条件——若余量恢复后不及时解冻，驻留区会因长期不更新而失效，命中率持续走低；若解冻过快，预取重新挤占带宽，SLO 余量再次收缩，形成振荡。工程判断是：冻结阈值与解冻阈值之间留出滞回带，且冻结期间仍允许每 <code>N</code> 步做一次轻量重排，只更新元数据不发起搬运，使解冻后能立即恢复有效预取。例子：一批长尾请求把 TPOT 分位数推到 SLO 边界，调度器冻结预取深度，已排队 token 的解码步不再被预取搬运打断，尾延迟回落；余量恢复后按滞回带解冻，热度表因冻结期间的轻量重排仍然可用，命中率没有出现解冻后的二次凹陷。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-13\">十三 · 预取收益判据与失效边界：每一步的输入、输出与代价</h3>\n<p>把预取决策从“热度表命中即搬”升级为“按收益搬”，是本方案在工程上可落地的关键。对每个候选专家 $e$，热度表给出下一层命中概率 $p_e$，当前层 GEMM 可掩盖时间 $T_{\\text{gemm}}$，搬运代价 $c_{\\text{prefetch}}$（HBM 读带宽占用与 L2 槽位占用之和），未命中回退惩罚 $c_{\\text{miss}}$（按需加载的 stall 与惩罚计数增量）。判据为：</p>\n<div class=\"formula\">$$G_e = p_e \\cdot T_{\\text{gemm}} - c_{\\text{prefetch}} - (1-p_e)\\,c_{\\text{miss}}$$</div>\n<p>只有 $G_e&gt;0$ 的专家才进入 cp.async 队列，其余留在热度表中但不预取。这一步的输入是上一 token 路由分布与热度表，输出是长度为 $k$ 的预取候选集；代价是每步一次轻量排序与判据计算，量级远小于一次专家搬运。判据的物理含义很直接：$p_e$ 低时 $c_{\\text{prefetch}}$ 是纯损失，因为预取错误会占用 HBM 带宽与 L2 容量，直接挤占注意力 KV 读取——解码阶段 KV 读取本身已是带宽敏感路径，预取错误相当于把宝贵的 HBM 周期花在了不会被用到的权重上，低命中率时整体反而变慢。$p_e$ 高时 $T_{\\text{gemm}}$ 足以掩盖搬运，收益为正。</p>\n<p>失效条件可以按判据的三个项分别定位。第一，$T_{\\text{gemm}}$ 收缩：小批或短序列时当前层 GEMM 时间不足以覆盖搬运，$G_e$ 转负，预取变成同步 stall 的伪装。第二，$p_e$ 失真：热度表依赖路由稳定性，分布漂移或长尾请求下命中率骤降，$p_e$ 的高估使大量 $G_e$ 误判为正，预取队列被错误专家占满，同时触发额外重排开销。第三，$c_{\\text{prefetch}}$ 被外部挤占：L2 容量与 HBM 带宽预算被 KV cache 或 All-to-All 分组通信占用时，预取的实际代价高于标称值。规模上限正受这两项预算约束，而非受算力约束。</p>\n<p>重排步骤的输入是每 $N$ 步累计的命中率 $h_l$ 与惩罚计数，输出是新的槽位分配；代价是一次表重写与槽位淘汰，若 $N$ 过小则重排本身成为开销，若 $N$ 过大则漂移响应滞后。SLO 逼近时冻结预取深度是另一条边界：冻结牺牲预取收益换取确定性，但若冻结策略不当——例如冻结后仍保留已发起的 cp.async 而不撤销——已排队 token 的尾延迟会被放大。工程判断是：冻结应同时停止新预取并让在途预取完成，把预算让给 KV 读取，而不是简单地把预取深度置零。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>判据筛选</td><td>热度表 $p_e$、$T_{\\text{gemm}}$</td><td>预取候选集</td><td>排序开销，可忽略</td></tr><tr><td>发起预取</td><td>候选集、L2 槽位</td><td>cp.async 在途搬运</td><td>HBM 带宽、L2 容量</td></tr><tr><td>命中/回退</td><td>第 $l+1$ 层路由</td><td>分组 GEMM 或按需加载</td><td>未命中 stall、惩罚计数</td></tr><tr><td>周期重排</td><td>$h_l$、惩罚计数</td><td>新槽位分配</td><td>表重写、淘汰抖动</td></tr></tbody></table>\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-14\">十四 · 把单步时间拆成三笔账</h3>\n<p>要判断双相预取到底赚不赚，先得把解码步的耗时写成可核算的形式。一个解码步在第 <span class=\"inline\">l</span> 层上花的时间，无非三块：真正做矩阵乘的 GEMM 时间、把下一层候选专家权重搬进 L2 或驻留区的预取时间、以及预取没盖住的那部分按需搬运造成的停顿。三块里只有第一块是\"必须付\"的，另外两块是\"可以重叠\"和\"应该被压缩\"的，工程优化的全部空间就在后两块。</p>\n<p>把第 <span class=\"inline\">l</span> 层的分组 GEMM 时间记为 <span class=\"inline-math\">$T^{\\text{gemm}}_{l}$</span>，它由本轮路由到该层的 token 数与专家数决定，基本贴着该层算力下界走；把第 <span class=\"inline\">l+1</span> 层的预取时间记为 <span class=\"inline-math\">$T^{\\text{pref}}_{l+1}$</span>，它由候选专家数、每个专家的权重字节数与 HBM 有效带宽共同决定；把未命中造成的按需搬运停顿记为 <span class=\"inline-math\">$T^{\\text{miss}}_{l}$</span>，它是唯一真正暴露在关键路径上的额外开销，权重系数就是未命中率 <span class=\"inline-math\">$1-h_{l}$</span>。</p>\n<div class=\"formula\">$$T_{\\text{step}}=\\sum_{l=1}^{L}\\Big(\\max\\big(T^{\\text{gemm}}_{l},\\ T^{\\text{pref}}_{l+1}\\big)+\\big(1-h_{l}\\big)\\,T^{\\text{miss}}_{l}\\Big),\\quad h_l=\\frac{|E^{\\text{hit}}_l|}{|E^{\\text{route}}_l|}$$</div>\n<p>逐项读这个式子。<span class=\"inline-math\">$T^{\\text{gemm}}_{l}$</span> 是\"当前层必须算完\"的时间，它是分母也是基线；<span class=\"inline-math\">$T^{\\text{pref}}_{l+1}$</span> 是\"为下一层提前备料\"的时间，它和 GEMM 是异步的，所以两者取 <span class=\"inline-math\">$\\max$</span> 而不是相加——这就是双相预取的全部经济性来源；<span class=\"inline-math\">$(1-h_{l})$</span> 是未命中率，乘上 <span class=\"inline-math\">$T^{\\text{miss}}_{l}$</span> 得到平均每步要额外付的停顿；<span class=\"inline-math\">$h_l$</span> 的定义是命中专家数除以路由专家数，注意分母用的是\"本轮路由到的专家集合\"而不是\"热度表里的候选集合\"，两者口径不同会导致命中率虚高，这一点在后面的估计误差小节会展开。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-15\">十五 · 推导的关键一步：为什么是取大而不是相加</h3>\n<p>把 <span class=\"inline-math\">$\\max$</span> 写成不等式更清楚。设当前层 GEMM 在时刻 <span class=\"inline-math\">$t_0$</span> 开始、在 <span class=\"inline-math\">$t_0+T^{\\text{gemm}}_{l}$</span> 结束；预取在 <span class=\"inline-math\">$t_0$</span> 同时发起（因为在算第 <span class=\"inline\">l</span> 层时，第 <span class=\"inline\">l+1</span> 层的路由分布已经能从上一 token 的直方图拿到），在 <span class=\"inline-math\">$t_0+T^{\\text{pref}}_{l+1}$</span> 完成。两者都是异步的，谁晚谁决定下一个可用时刻：</p>\n<div class=\"formula\">$$t_{\\text{ready}}=\\max\\big(t_0+T^{\\text{gemm}}_{l},\\ t_0+T^{\\text{pref}}_{l+1}\\big)$$</div>\n<p>这一步的推导关键在于：预取必须在\"当前层算完之前\"发起，否则它就不再是重叠而是串行。很多实现把预取放在第 <span class=\"inline\">l</span> 层 GEMM 结束之后才发起，看起来仍然是\"提前一层\"，但时间线变成了 <span class=\"inline-math\">$T^{\\text{gemm}}_{l}+T^{\\text{pref}}_{l+1}$</span>，白白丢掉了重叠窗口，这是最常见的性能塌方原因之一。真正的双相预取要求预取指令和 GEMM 指令在同一个 warp 调度周期内交错发射，靠 <code>cp.async</code> 的异步拷贝语义把搬运压进计算阴影里。</p>\n<p>再看未命中项。如果预取完全重叠且命中，<span class=\"inline-math\">$h_l=1$</span>，惩罚项归零，单步时间就是 <span class=\"inline-math\">$\\sum_l \\max(T^{\\text{gemm}}_l, T^{\\text{pref}}_{l+1})$</span>；如果预取全部落空，<span class=\"inline-math\">$h_l=0$</span>，每个未命中专家都要在关键路径上等一次 HBM 往返，单步时间退化成按需加载的原始形态。所以这个式子的两端是两个已知基准，双相预取的价值就是把实际曲线往左端推。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-16\">十六 · 命中率不是免费的：估计误差怎么进惩罚项</h3>\n<p>式子里 <span class=\"inline-math\">$h_l$</span> 是\"实际命中率\"，但工程上你能拿到的只是\"热度表预测的命中率\"，两者之间有估计误差。设热度表给出的候选集合为 <span class=\"inline-math\">$E^{\\text{cand}}_l$</span>，实际路由集合为 <span class=\"inline-math\">$E^{\\text{route}}_l$</span>，那么真正的命中数只能来自两者交集，即 <span class=\"inline-math\">$|E^{\\text{cand}}_l \\cap E^{\\text{route}}_l|$</span>。把候选集合的规模记为 <span class=\"inline-math\">$k$</span>，路由集合规模记为 <span class=\"inline-math\">$m$</span>，则一个粗糙的上界是：</p>\n<div class=\"formula\">$$h_l \\le \\frac{\\min(k,\\ m)}{m},\\qquad T^{\\text{miss}}_{l}\\approx \\frac{B_{\\text{exp}}\\cdot S_{\\text{exp}}}{B_{\\text{eff}}}$$</div>\n<p>第二式里 <span class=\"inline-math\">$B_{\\text{exp}}$</span> 是单个专家权重的字节数，<span class=\"inline-math\">$S_{\\text{exp}}$</span> 是同时未命中的专家数，<span class=\"inline-math\">$B_{\\text{eff}}$</span> 是 HBM 有效带宽。它说明一件很实际的事：<strong>惩罚项与未命中专家数是线性的，而预取成本与候选数是线性的</strong>，两者都是线性，所以不存在\"多预取一定更好\"的结论——多预取抬高 <span class=\"inline-math\">$T^{\\text{pref}}$</span>，一旦超过 <span class=\"inline-math\">$T^{\\text{gemm}}$</span> 就把 <span class=\"inline-math\">$\\max$</span> 顶起来了，收益立刻变成负的。最优预取深度 <span class=\"inline-math\">$k^{*}$</span> 满足 <span class=\"inline-math\">$T^{\\text{pref}}(k^{*})\\approx T^{\\text{gemm}}_{l}$</span>，也就是\"刚好把 GEMM 的阴影填满\"，再深就是浪费带宽。</p>\n<p>还有一个二阶效应值得写进推导：热度表是按上一 token 的路由统计出来的，而解码步的路由在 token 之间是有惯性的（同一语义上下文下专家激活高度相关），但惯性会随生成长度衰减。设相关性衰减系数为 <span class=\"inline-math\">$\\gamma$</span>（每步衰减一次），则第 <span class=\"inline-math\">$t$</span> 步的预测命中率大致是 <span class=\"inline-math\">$h_l(t)\\approx h_l(0)\\,\\gamma^{t}$</span>。这就是为什么热度表要\"每 N 步重排一次\"——不是为了追求更高命中率，而是为了把 <span class=\"inline-math\">$\\gamma^{t}$</span> 的衰减拉回起点，让长期解码不退化。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-17\">十七 · 伪代码：把式子落到可实现的循环里</h3>\n<pre><code># 每层解码步的调度骨架（单卡视角，EP 内部同理）\nfor l in range(L):\n    # 1) 拿到本层实际路由（由 gate 计算，已在上一阶段完成）\n    route = gate_route(hidden[l])\n    hit, miss = split_by_cache(route, cache_slot[l])\n\n    # 2) 异步预取下一层：只发起，不等待\n    cand = heat_table[l + 1][:k_l]           # 候选集合，规模 k_l\n    for e in cand:\n        if not cache_contains(l + 1, e):\n            cp_async_prefetch(weight[l + 1][e])   # 异步，压进 GEMM 阴影\n\n    # 3) 本层 GEMM：命中走驻留区，未命中走按需加载\n    out = grouped_gemm(hidden[l], weight_of(hit))\n    out += on_demand_gemm(hidden[l], weight_of(miss))   # 暴露在关键路径\n\n    # 4) 记账：命中率与惩罚计数，供重排使用\n    h[l] = len(hit) / max(1, len(route))\n    penalty[l] += len(miss)\n\n    # 5) 等预取落地（与下一步 GEMM 重叠，不是串行等待）\n    cp_async_wait_group(0)\n\n    # 6) 每 N 步重排热度表：按命中率与惩罚计数淘汰低收益槽位\n    if step % N == 0:\n        heat_table[l + 1] = resort(heat_table[l + 1], h[l], penalty[l])\n</code></pre>\n<p>伪代码里有三个容易写错的点。第一，<code>cp_async_prefetch</code> 必须在 GEMM 之前发起，而不是之后；第二，<code>cp_async_wait_group</code> 要等到\"下一步 GEMM 开始前\"才生效，不能在本层 GEMM 中途阻塞；第三，重排热度表要按\"每层独立\"进行，不能用全局统一的重排节奏——不同层的路由分布收敛速度不一样，浅层专家切换快、深层专家切换慢，统一节奏会让浅层过热、深层欠热。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-18\">十八 · 参数档位与退化边界</h3>\n<p>把上面的式子当成设计表来读，能直接读出每个参数该取什么量级。预取深度 <span class=\"inline-math\">$k$</span> 由 <span class=\"inline-math\">$T^{\\text{pref}}(k)\\approx T^{\\text{gemm}}$</span> 定，实践中通常是每层路由专家数的 1.2 到 1.5 倍；重排周期 <span class=\"inline-math\">$N$</span> 由相关性衰减 <span class=\"inline-math\">$\\gamma$</span> 定，<span class=\"inline-math\">$\\gamma$</span> 越小 <span class=\"inline-math\">$N$</span> 越短，经验值落在 8 到 32 步之间；驻留区容量则由 L2 预算除以层数再除以专家字节数得到，超过这个容量就必须做槽位竞争，而不是无限扩表。</p>\n<table>\n<thead><tr><th>参数</th><th>决定它的式子</th><th>典型量级</th><th>取错的后果</th></tr></thead>\n<tbody>\n<tr><td>预取深度 <span class=\"inline-math\">$k$</span></td><td><span class=\"inline-math\">$T^{\\text{pref}}(k)\\approx T^{\\text{gemm}}_{l}$</span></td><td>路由专家数的 1.2–1.5 倍</td><td>过深则预取顶起 <span class=\"inline-math\">$\\max$</span>，收益转负</td></tr>\n<tr><td>重排周期 <span class=\"inline-math\">$N$</span></td><td><span class=\"inline-math\">$h_l(t)\\approx h_l(0)\\gamma^{t}$</span></td><td>8–32 步</td><td>过长则长解码命中率塌方</td></tr>\n<tr><td>驻留区容量</td><td>L2 预算 ÷ 层数 ÷ 专家字节数</td><td>每层数十个专家槽位</td><td>超容则槽位竞争，命中率不升反降</td></tr>\n<tr><td>chunk 长度</td><td>每 chunk 覆盖每层至少一次完整路由采样</td><td>绑定层数与 EP 度</td><td>过短则直方图不收敛，热度表失真</td></tr>\n</tbody>\n</table>\n<p>最后说退化边界。这个式子在两种负载下会失效：一是极短请求（预填 chunk 不足以统计出稳定的路由直方图，<span class=\"inline-math\">$h_l(0)$</span> 本身就是噪声），二是路由分布剧烈漂移的负载（<span class=\"inline-math\">$\\gamma$</span> 接近 0，热度表刚写入就过期）。前者应该退回纯按需加载并只保留固定缓存，后者应该缩短重排周期甚至改成\"每步重估\"，而不是硬套双相节奏。把这三种形态的切换判据写进调度器，比把参数调到极致更重要。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-19\">十九 · 一个数值算例：命中率差 0.2 意味着什么</h3>\n<p>把式子代入一组典型量级，能看清命中率的敏感度。设某层 GEMM 时间 <span class=\"inline-math\">$T^{\\text{gemm}}_{l}=80\\,\\mu s$</span>，单个专家权重 <span class=\"inline-math\">$B_{\\text{exp}}=48\\,MB$</span>（NVFP4 权重加微缩放因子），HBM 有效带宽 <span class=\"inline-math\">$B_{\\text{eff}}=3.2\\,TB/s$</span>，则单次未命中搬运约 <span class=\"inline-math\">$48/3200\\approx 15\\,\\mu s$</span>。若该层路由到 8 个专家、命中 6 个（<span class=\"inline-math\">$h_l=0.75$</span>），惩罚项为 <span class=\"inline-math\">$2\\times 15=30\\,\\mu s$</span>；单步时间从纯命中的 <span class=\"inline-math\">$80\\,\\mu s$</span> 抬到 <span class=\"inline-math\">$110\\,\\mu s$</span>，恶化 37.5%。若命中率再掉到 0.5，惩罚项变成 <span class=\"inline-math\">$4\\times 15=60\\,\\mu s$</span>，单步时间 <span class=\"inline-math\">$140\\,\\mu s$</span>，恶化 75%。</p>\n<p>这个算例给出两条可操作的结论。第一，<strong>命中率对单步时间的敏感度是线性的，且斜率等于单个未命中搬运时间</strong>，所以\"命中率提高 10 个百分点\"值多少时间，直接用路由专家数乘 0.1 再乘 15 微秒就能估出来，不需要做完整的性能剖析。第二，当预取时间 <span class=\"inline-math\">$T^{\\text{pref}}_{l+1}$</span> 小于 <span class=\"inline-math\">$T^{\\text{gemm}}_{l}$</span> 时，预取是\"免费\"的，此时唯一该优化的就是命中率；一旦预取时间超过 GEMM 时间，<span class=\"inline-math\">$\\max$</span> 项开始由预取主导，此时再提高命中率的边际收益会被预取成本抵消，优化的重心应转向压缩候选集合。</p>\n<table>\n<thead><tr><th>命中率 <span class=\"inline-math\">$h_l$</span></th><th>未命中专家数</th><th>惩罚项</th><th>单步时间</th><th>相对纯命中恶化</th></tr></thead>\n<tbody>\n<tr><td>1.00</td><td>0</td><td>0 μs</td><td>80 μs</td><td>—</td></tr>\n<tr><td>0.75</td><td>2</td><td>30 μs</td><td>110 μs</td><td>37.5%</td></tr>\n<tr><td>0.50</td><td>4</td><td>60 μs</td><td>140 μs</td><td>75.0%</td></tr>\n<tr><td>0.25</td><td>6</td><td>90 μs</td><td>170 μs</td><td>112.5%</td></tr>\n</tbody>\n</table>\n<p>表里最后一行值得警惕：命中率 0.25 时单步时间已经超过按需加载的朴素形态（朴素形态没有预取开销，只有全部未命中的惩罚），也就是说<strong>低命中率的双相预取比不做预取更慢</strong>。这正是\"预热表写错\"最危险的后果——它不报错，只是把系统悄悄拖慢，监控上表现为 TPOT 分位数缓慢漂移，很容易被误判成上游负载变化。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-20\">二十 · 三条判据把\"该不该用\"钉死</h3>\n<p>把前面的推导收成三条上线判据，可以直接写进调度器的准入检查。第一条是命中率判据：预热表预测的 <span class=\"inline-math\">$h_l(0)$</span> 必须高于由式子反解出的临界值，低于它就该退回按需加载；第二条是重叠判据：<span class=\"inline-math\">$T^{\\text{pref}}(k)$</span> 必须不超过 <span class=\"inline-math\">$T^{\\text{gemm}}_{l}$</span> 的 1.1 倍，超过就缩候选集；第三条是稳定性判据：相邻两次重排之间命中率的下降幅度不能超过设定阈值，超过就说明路由漂移太快，应缩短重排周期或改用每步重估。</p>\n<p>这三条判据的共同点是都可从运行时计数器直接算出来，不需要离线剖析：命中数与路由数来自缓存槽位的计数器，预取时间可由 <code>cp.async</code> 的完成时间戳减去发起时间戳得到，GEMM 时间由 kernel 计时器给出。把它们做成每层的滑动窗口指标，就能让双相预取在负载变化时自动降级，而不是靠人工调参。这也是把\"公式\"变成\"运维能力\"的最后一步——式子本身只是解释，能自动读出参数该往哪边走，才是它真正的用处。</p>\n<p>还有一处容易被忽略的记账细节：式子里 <span class=\"inline-math\">$T^{\\text{miss}}_{l}$</span> 只算了搬运本身，没有算搬运期间 SM 的占用。真实的按需加载路径上，一个未命中的专家往往会让整组 token 的分组 GEMM 等它，等待的粒度不是\"这个专家\"，而是\"这一批里所有路由到该专家的 token\"。所以当某层路由很分散（每个 token 打到不同专家）时，单个未命中会拖住一整个 micro-batch 的进度，实际惩罚远大于单专家搬运时间。工程上的对策是把未命中专家按\"是否被同批多 token 共享\"排序，优先按需加载共享度高的专家，把零散专家的惩罚摊薄到后续步，这一排序本身就值几个百分点的 TPOT。</p>\n<p>最后要强调的是这个式子的适用前提：它假设预取与 GEMM 共享同一根 HBM 总线，且 L2 容量足够让预取落地的数据不被挤出。一旦 L2 被 KV 页或其他驻留区挤占，预取数据在到达时已经被驱逐，命中率会掉到零而时间线看起来一切正常——这是双相预取最难查的静默故障，必须把 L2 占用率与预取命中率放在同一张监控图上看，才能区分\"路由变了\"和\"缓存被挤没了\"。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-21\">二十一 · 请求形态：为什么变长对话是这套机制的“原生负载”</h3>\n<p>双相专家预取的经济学前提，是预填相能免费拿到一份“可代表解码相”的路由直方图。这个前提在负载层面的直接推论是：请求必须足够长、且解码相的路由分布与预填相统计窗口内的分布同源。变长对话恰好满足这两点——一轮对话的预填 chunk 覆盖了系统提示、历史轮次与当前用户输入，路由直方图统计的是同一语义上下文下的专家激活倾向；随后几十到几百个解码步在这个上下文上继续生成，路由自然落在同一批专家邻域内。热度表因此不是猜的，而是从同一请求的前半段外推后半段。</p>\n<p>反过来，短请求是这套机制的结构性弱点。一个只有几十个输入 token、输出十几个 token 的请求，预填 chunk 太小，直方图统计粒度不足以把专家热度区分开：每层路由到的专家数本就接近激活上限，直方图趋于平坦，热度表退化为“均匀预取”，预取深度铺开却命中率不高。更糟的是这类请求的解码步数少，预取投入的搬运代价摊不到足够的 GEMM 时间上，收益判据 $G_e$ 里 $p_e\\cdot T_{\\text{gemm}}$ 项被压得很小，而 $c_{\\text{prefetch}}$ 是实打实付出的。工程判断很直接：短请求占比高的负载，应当把预取深度压到 1 层甚至关闭预取，只保留热度表的跨请求复用价值。</p>\n<p>请求形态还有第三个维度：单轮 vs 多轮。多轮对话的后续轮次可以复用上一轮留下的热度表作为初值，预填相只需做增量修正而非从零统计，这让重排开销摊薄。单轮批量任务（如批量摘要、批量分类）没有这种跨轮复用，每个请求都要独立走一遍“统计—生成—预取”流程，预填相的直方图统计虽然几乎零额外开销，但热度表的冷启动质量取决于该请求自身的输入长度。批量任务的输入往往等长且模板化，路由分布高度集中，这反而对预取有利——模板化输入的专家集合几乎固定，热度表一次生成即可长期有效。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-22\">二十二 · 长度分布：预填 chunk 粒度与解码步数的耦合</h3>\n<p>预填相按 chunk 切分，这个切分粒度同时服务两个目的：控制直方图统计的样本量，以及控制预填相本身的调度弹性。chunk 太小，每层的路由计数噪声大，热度表排序不稳；chunk 太大，预填相占用 SM 的时间变长，挤占同期解码请求的算力，破坏在线服务的 TPOT 分位数约束。长度分布决定了这个权衡的落点：输入长度集中在数千 token 的负载，可以把 chunk 设得较大，一次统计就得到统计显著的直方图；输入长度分布方差大的负载，chunk 必须设小以适配最短请求，代价是长请求要跨多个 chunk 累积直方图，热度表在预填相结束前才最终定型。</p>\n<p>解码步数与预取深度的关系可以用一个简单的摊销思路刻画。设预取一层专家的搬运代价为 $c_{\\text{prefetch}}$，该层 GEMM 可掩盖时间为 $T_{\\text{gemm}}$，若请求解码 $S$ 步，则预取的总投入约为 $S\\cdot d\\cdot c_{\\text{prefetch}}$（$d$ 为预取深度），总收益约为 $S\\cdot d\\cdot h\\cdot T_{\\text{gemm}}$，其中 $h$ 为该深度的平均命中率。$S$ 足够大时，投入与收益同步放大，命中率 $h$ 成为唯一决定符号的量；$S$ 很小时，固定开销（热度表生成、首步预取的冷启动）无法摊薄，即使 $h$ 很高也可能净亏。这就是为什么长度分布里“输出长度”这一维比“输入长度”更关键：它直接决定预取投入能否摊销。</p>\n<div class=\"formula\">$$S^{*}=\\frac{c_{\\text{table}}}{d\\,(h\\,T_{\\text{gemm}}-c_{\\text{prefetch}})}$$</div>\n<p>式中 $c_{\\text{table}}$ 为热度表生成与首次写入槽位的固定代价，$S^{*}$ 是预取开始净收益为正的解码步数阈值。这个式子不给具体数值，但给出方向：命中率 $h$ 越接近 1、$T_{\\text{gemm}}$ 越长（层 GEMM 越重、批越大），阈值越低，短输出请求也能受益；反之 $h$ 稍低就会把阈值推到几百步，短请求全部落入亏损区。长度分布分析的落点就是估算这个阈值落在分布的哪个分位上。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-23\">二十三 · 并发与批大小：驻留区容量是硬约束，L2 预算是软约束</h3>\n<p>批大小在这套机制里不是自由参数，它被两个容量边界夹住。第一个是显存驻留区：每层热度表选出的驻留专家集合要常驻，其占用为 $\\sum_l |E^{\\text{resident}}_l|\\cdot s_e$，$s_e$ 为单专家权重大小（NVFP4/FP8 量化后显著压缩）。批越大，同时在解码的请求越多，它们共享同一份按层组织的驻留区——注意驻留区是按层而非按请求组织的，多请求共享热度表正是跨请求复用的来源。第二个是 L2 预算：预取中的专家要经 L2 中转，L2 同时承载注意力 KV 的读取流，预取占用的 L2 容量直接压缩 KV 读取的有效带宽。</p>\n<p>并发上升时，两个边界的表现不同。驻留区是硬墙：批大小超过驻留区容量对应的上限，要么淘汰槽位降低命中率，要么把部分专家退回按需加载，两种都是收益衰减。L2 是软约束：预取挤占 KV 带宽不会立刻失败，但会拉长注意力部分的访存延迟，在 TPOT 分位数上表现为整体抬升而非长尾。因此并发规划的正确做法是先按驻留区容量定批大小上限，再用 L2 预算决定预取深度 $d$——深度是可调的减压阀，批大小不是。</p>\n<table class=\"mini\"><thead><tr><th>并发档位</th><th>驻留区状态</th><th>L2 压力</th><th>建议动作</th></tr></thead><tbody><tr><td>低并发</td><td>槽位充裕</td><td>宽松</td><td>加深预取深度，吃满 GEMM 掩盖窗口</td></tr><tr><td>中并发</td><td>接近容量</td><td>开始挤占 KV</td><td>预取深度收到 1–2 层，按 $G_e$ 排序只留高收益专家</td></tr><tr><td>高并发</td><td>超容</td><td>KV 带宽明显受压</td><td>冻结预取深度，热度表只做淘汰不做扩张</td></tr></tbody></table>\n<p>具体例子：一个在线对话服务，批内并发从数十升到上百，若仍按低并发时的预取深度运行，预取搬运会与注意力 KV 读取争抢 HBM 带宽，表现为 TPOT 的 P99 不降反升——预取本意是收敛长尾，结果因为挤占 KV 反而制造了新的长尾。这正是失败模式里“预取错误挤占 HBM 带宽与 L2 容量、压低注意力 KV 读取带宽”的负载侧成因。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-24\">二十四 · 负载不对时的三种退化形态</h3>\n<p>第一种退化是命中率坍塌。路由分布漂移——比如服务从通用对话切到代码生成、或用户群体语义分布突变——会让预填相统计出的热度表迅速过期。此时 $p_e$ 系统性偏低，$G_e$ 转负，预取变成纯负担：搬运了不用的专家，占了 L2，还没省下任何 stall。惩罚计数会累积，周期性重排能纠正，但重排本身有开销，且重排周期 $N$ 内的解码步全部在低命中率下运行。漂移越快，$N$ 内浪费的比例越高。</p>\n<p>第二种退化是长尾请求主导。少量超长请求的解码步极多，它们的路由在生成过程中持续演化，热度表在请求早期生成的专家集合到后期已不适用。这些请求恰好是 TPOT 长尾的主要贡献者，也是预取最想救的对象，但它们恰恰最难被预填统计代表。结果是预取对短请求过度服务、对长尾请求服务不足，长尾没收敛，平均吞吐还掉了。</p>\n<p>第三种退化是批构成失衡。批内混入大量短输出请求时，这些请求的解码步数低于 $S^{*}$，它们的预取投入无法摊销，却与长请求共享同一份 L2 和带宽预算，等于用长请求的收益补贴短请求的亏损。连续批处理下批构成动态变化，这种失衡会随调度波动反复出现。</p>\n<ul><li>命中率坍塌：$p_e$ 系统性偏低，$G_e&lt;0$，预取纯亏，重排周期内持续浪费。</li><li>长尾主导：预取服务不到最需要的请求，长尾未收敛而吞吐下降。</li><li>批构成失衡：短输出请求摊不薄固定代价，挤占长请求的带宽预算。</li></ul>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-25\">二十五 · 负载适配的工程判据：先量分布，再定配方</h3>\n<p>部署前应采集三张分布：输入长度分布、输出长度分布、以及路由直方图的跨请求稳定性（可用相邻请求热度表的排序相关性做定性判断，不引入新指标）。输入长度分布决定 chunk 粒度；输出长度分布决定 $S^{*}$ 落在哪个分位、预取是否值得开；路由稳定性决定热度表复用是否有意义。三者合起来给出配方：输出长度中位数远高于 $S^{*}$ 且路由稳定，全量开启预取并按 $G_e$ 排序；输出长度集中在 $S^{*}$ 以下，只保留热度表做槽位管理、关闭异步预取；路由稳定性差，缩短重排周期 $N$ 并降低预取深度，把机制退化为“带惩罚计数的按需加载加轻量驻留”。</p>\n<p>运行时的判据则挂在命中率与惩罚计数上：命中率 $h_l$ 连续多个重排周期低于阈值，说明负载已偏离配方假设，应主动收深度；惩罚计数在某一层异常集中，说明该层专家集合对当前负载过于发散，应把该层从预取范围剔除、退回按需加载。SLO 逼近时冻结预取深度是最后一道闸，但冻结策略要选“冻结深度、保留淘汰”，而不是“冻结全部”——后者会让已排队 token 在低命中率的驻留区上继续跑，尾延迟被放大。负载配方的本质是把预取从“默认开启”变成“按分布证据开启”，证据不足时宁可退回按需加载，也不让预取在错误的路由上持续消耗 HBM 带宽与 L2 容量。</p>\n\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-26\">二十六 · 负载配方：命中率、批大小与路由稳定性的三角约束</h3>\n<p>这套方案不是普适加速器，它的收益完全由负载的统计结构决定。核心判据是逐专家的预取收益：<div class=\"formula\">$$G_e = p_e \\cdot T_{\\text{gemm}} - c_{\\text{prefetch}} - (1-p_e)\\,c_{\\text{miss}}$$</div>只有当热度表给出的命中概率 $p_e$ 足够高、当前层 GEMM 可掩盖时间 $T_{\\text{gemm}}$ 足够长时，$G_e$ 才为正。换言之，负载必须让“下一层专家集合”在跨 token、跨请求意义上可预测。变长对话、批量并发的在线服务正好满足：同一系统提示词、同一领域语料下的连续解码步路由高度集中，预填相按 chunk 切分统计出的直方图能代表解码分布，热度表可跨请求复用。反之，开放式多主题混合流量、每请求独立 system prompt 的网关型服务，路由直方图在请求间几乎无重叠，$p_e$ 趋近随机基线，预取变成纯粹的带宽浪费。</p>\n<p>批大小与驻留区容量构成第二个约束。驻留区占用按 $B \\cdot |E^{\\text{route}}_l| \\cdot s_e$（$s_e$ 为单专家量化后字节数）估算，NVFP4/FP8 压缩能放大可驻留专家数，但 L2 预取窗口与注意力 KV 读取共享同一带宽池。批越大，单步 GEMM 越长、$T_{\\text{gemm}}$ 越充裕，掩盖窗口越好；但批越大也意味着路由集合越分散，$h_l$ 下降。存在一个由 L2 预算与 HBM 带宽共同决定的最优批区间：低于它掩盖不足，高于它命中率塌陷。工程上应以 TPOT 分位数为约束反推批大小，而不是先定批再测延迟。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>命中率走向</th><th>系统代价</th></tr></thead><tbody><tr><td>同领域变长对话、共享前缀</td><td>$h_l$ 高且稳定，热度表跨请求复用</td><td>预取带宽被 GEMM 掩盖，TPOT 长尾收敛</td></tr><tr><td>多主题混合、请求间无重叠</td><td>$h_l$ 接近随机，$G_e&lt;0$</td><td>预取挤占 KV 读取带宽，整体变慢</td></tr><tr><td>长尾请求占比高、路由快速漂移</td><td>周期性重排仍追不上漂移</td><td>重排开销叠加未命中惩罚，尾延迟放大</td></tr></tbody></table>\n<p>失效路径有三条，且互相耦合。其一，预取错误占用 HBM 带宽与 L2 容量，直接压低注意力 KV 读取的有效带宽——解码阶段 KV 读取本就是带宽敏感路径，被挤占后单步时间不降反升。其二，热度表依赖路由稳定性，分布漂移（新话题涌入、多轮对话主题切换）使 $h_l$ 骤降，每 $N$ 步的重排从“微调”变成“追尾”，重排本身消耗调度与统计开销。其三，SLO 逼近时冻结预取深度虽能保住已排队 token 的解码步，但冻结策略若一刀切，会把仍有正收益的专家预取一并停掉，尾延迟反而被放大。因此负载配方的实质是：先验证路由直方图在请求间的可复用性，再按 L2 预算定批，最后把冻结策略做成按 $G_e$ 排序的渐进式降级，而非全局开关。</p>\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-27\">二十七 · 硬件档位：把 L2 预算当作一等资源</h3>\n<p>双相预取不是算力问题，是带宽与容量问题。选档位的唯一判据是：<strong>每层驻留区容量 × 层数</strong> 必须落在 L2 可承受的范围内，同时 HBM 带宽要能同时喂饱三件事——当前层 GEMM 的权重流、注意力 KV 读取、以及 cp.async 预取流量。三者共享同一根 HBM 总线，预取流量是纯粹的“透支”，一旦命中率不够就是净损失。因此硬件档位的第一条不是看峰值算力，而是看 <em>HBM 带宽 / L2 容量</em> 的比值：比值越高，预取深度可以开得越深；比值越低，就必须把预取深度压到 1–2 层，靠热度表的精度而不是靠深度取胜。</p>\n<p>在 SM100/SM103 这一档上，B200 与 GB200 NVL72 的差别不在单卡，而在拓扑。NVL72 机柜内 NVLink 5 域把 72 个 GPU 连成一个高带宽域，专家并行的 All-to-All 走域内链路，专家权重的“搬运”在物理上分为两级：跨 HBM 的本地搬运与跨 NVLink 的远端搬运。预取机制只对本地 HBM→L2 这一段负责；远端专家的驻留决策属于并行拓扑层面，由专家放置策略决定。把这两级混在一起设计，是部署阶段最常见的错误：远端专家本来就不该进本地 L2 驻留区，它的代价模型里 $c_{\\text{prefetch}}$ 是 NVLink 传输而非 HBM 读取，收益判据完全不同。</p>\n<p>具体档位选择上，给出一个可操作的判据：设单层专家权重总量为 $W_E$，驻留槽位数为 $S$，则驻留区占用为 $S \\cdot W_E / |E|$。当量化到 NVFP4 时 $W_E$ 压缩到 FP8 的一半左右，同样的 L2 预算能容纳的槽位数翻倍——这是量化方案与缓存策略必须联合设计的原因，而不是先定量化再定缓存。工程上把“每卡 L2 可用于专家驻留的比例”作为一个显式配置项（例如以 1/4 或 1/3 为档），剩余部分留给 KV 与激活，这个比例直接决定 $S$，进而决定热度表长度与重排周期 $N$。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-28\">二十八 · 并行拓扑：专家放置与预取域的边界</h3>\n<p>预取的物理作用域必须与专家并行的切分方式对齐。在专家并行（EP）下，每个 rank 只持有部分专家，路由产生的 All-to-All 把 token 送到持有目标专家的 rank。此时“预取”在语义上分裂为两件事：一是本地 rank 上已持有专家的 HBM→L2 提升，二是远端 rank 上专家被访问前的“预热”——后者不是 cp.async 能解决的，它依赖 All-to-All 的调度顺序。部署配方因此要求：<strong>热度表按 rank 本地视角生成</strong>，只对本地持有的专家排序，远端专家的热度信息用于调整 All-to-All 的发送批次顺序，让高热度远端专家对应的 token 批次先发，从而让远端 rank 的本地预取有更长的掩盖窗口。</p>\n<p>拓扑档位与预取深度的对应关系可以写成一条经验规则：域内 NVLink 带宽充裕时，远端专家的到达延迟被通信掩盖，本地预取只需覆盖本地专家；跨域（例如多机 scale-out）时，远端延迟不可忽略，预取深度需要额外加一层来覆盖“通信后立即计算”的空窗。这就是为什么 NVL72 这种全连接域内拓扑对双相预取特别友好——它把远端专家的 $c_{\\text{miss}}$ 压得很低，使得 $G_e$ 判据中 $(1-p_e)c_{\\text{miss}}$ 项变小，热度表允许更保守（更短、更频繁重排），从而节省 L2。</p>\n<p>代价侧要算清楚：EP 度数为 $P$ 时，每 rank 持有 $|E|/P$ 个专家，热度表长度随之缩短，重排开销按 $O(|E|/P \\log(|E|/P))$ 下降；但 All-to-All 的通信量随 $P$ 上升，token 在 rank 间的往返会稀释预取收益。存在一个最优点：当 All-to-All 时间开始接近单层 GEMM 时间时，预取的掩盖窗口被通信吃掉，继续增大 $P$ 只增加通信开销而不增加命中收益。部署时以“单层 GEMM 时间 / All-to-All 时间”作为拓扑档位的选择指标，比值大于 1 才值得加深预取。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-29\">二十九 · 量化方案：驻留区占用与精度损失的联合取舍</h3>\n<p>量化在这里的角色不是提升算力，而是<strong>放大驻留区容量</strong>。NVFP4 的微缩放格式把专家权重压到 4 bit 量级，使同样 L2 预算下的槽位数成倍增加，直接抬高热度表的覆盖比例 $h_l$。但量化引入两个必须显式建模的代价：一是反量化（dequant）在分组 GEMM 前的额外指令开销，会侵占本可用于掩盖预取的 GEMM 时间 $T_{\\text{gemm}}$；二是低比特权重的精度损失在专家被高频命中时被放大——命中路径走的是驻留的低比特副本，未命中路径回退到高精度按需加载，两条路径的数值不一致会在同一 batch 内产生精度抖动。</p>\n<p>部署配方要求量化方案与回退路径解耦：驻留区存放 NVFP4 副本用于快速命中，回退路径从 HBM 读取 FP8 或更高精度副本。这样命中率高的专家走低比特快路径，命中率低的专家自然走精度路径，形成按热度分层的精度策略。收益判据需要修正为：</p>\n<div class=\"formula\">$$G_e = p_e \\cdot (T_{\\text{gemm}} - T_{\\text{dequant}}) - c_{\\text{prefetch}} - (1-p_e)\\,c_{\\text{miss}}$$</div>\n<p>其中 $T_{\\text{dequant}}$ 是命中路径的反量化开销。当 $T_{\\text{dequant}}$ 接近 $T_{\\text{gemm}}$ 时，预取的掩盖窗口被吃掉，此时应降低预取深度或改用 FP8 驻留以换取更小的反量化开销。工程判断：解码相 batch 较小时 GEMM 时间短，NVFP4 的反量化占比上升，宜用 FP8；batch 较大、GEMM 时间被拉长时，NVFP4 的容量收益占优。这一条直接对应调度参数中的批大小档位。</p>\n<p>显存侧的代价同样要算：驻留区占用与 KV cache 争抢同一块 HBM。量化把专家权重压小，等价于把更多 HBM 让给 KV，这是双相预取与分页 KV 共存的前提。部署时把“专家驻留区 HBM 配额”与“KV 分页池配额”作为两个独立可调参数，而不是让运行时自动挤占——自动挤占会在 SLO 逼近时引发预取与 KV 读取的带宽互踩，正是失败模式里描述的那条路径。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-30\">三十 · KV 策略：按相切换的读取优先级</h3>\n<p>预填相与解码相的 KV 访问模式截然不同：预填相是长序列一次性写入、带宽密集、对延迟不敏感；解码相是每步读取全部历史 KV、对首字节延迟极度敏感。双相预取要求 KV 策略也按相切换，否则预取流量与 KV 读取在同一根 HBM 总线上互相挤压。部署配方给出两条规则：预填相把 KV 写入批量化、允许更高的写入延迟以换取带宽利用率；解码相把 KV 读取置于预取流量之上，预取的 cp.async 优先级低于 KV 读取，且在 SLO 逼近时首先冻结预取而不是冻结 KV。</p>\n<p>具体机制上，解码相的 KV 读取是每层注意力的固定开销，它与专家预取共享 L2。当驻留区占满 L2 时，KV 的 L2 命中率下降，注意力读取回落到 HBM，直接拉长 TPOT。因此 KV 策略的核心是<strong>给 KV 留出 L2 的保底份额</strong>，驻留区只能使用剩余部分。这个保底份额随 batch 变化：batch 越大，KV 工作集越大，保底份额越高，驻留槽位数 $S$ 相应收缩。调度参数中的批大小上限因此不是由算力决定，而是由“KV 保底 + 驻留区”的 L2 分割决定。</p>\n<p>代价量化：设 KV 保底份额为 $\\alpha$，则驻留区可用 $1-\\alpha$，槽位数 $S \\propto (1-\\alpha)$。$\\alpha$ 每提高一档，命中率 $h_l$ 下降，$T_{\\text{miss}}$ 项上升。存在一个 $\\alpha$ 的平衡点，使 $T_{\\text{step}}$ 最小——这正是公式中 $\\max(T^{\\text{gemm}}_l, T^{\\text{pref}}_{l+1}) + (1-h_l)T^{\\text{miss}}_l$ 两项的拉锯。部署时以 TPOT 分位数作为观测量，二分搜索 $\\alpha$，而不是拍脑袋定一个固定比例。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-31\">三十一 · 调度参数：批大小、chunk 粒度与重排周期</h3>\n<p>调度层要暴露四个参数：批大小上限、预填 chunk 粒度、热度表重排周期 $N$、预取深度。它们不是独立的，而是被同一条约束串起来：批大小决定 KV 工作集与 GEMM 时间，chunk 粒度决定路由直方图的统计精度，$N$ 决定热度表对分布漂移的响应速度，预取深度决定 L2 透支量。部署配方要求把这四个参数写进一个配置文件，并按硬件档位给出预设，而不是让运行时自适应——自适应在 SLO 逼近时容易震荡。</p>\n<p>chunk 粒度与直方图精度的关系是：chunk 越小，每层路由直方图的样本越少，统计噪声越大，热度表越不可靠；chunk 越大，预填相的路由统计越能代表解码分布，但预填的尾延迟变长。工程上取“单 chunk 覆盖的 token 数足以让每层每个专家的期望命中计数达到个位数”作为下限，这是统计可靠性的最低要求，也是热度表能跨请求复用的前提。跨请求复用是这套方法的核心收益之一，它要求直方图在请求之间可比较，因此 chunk 粒度必须稳定，不能随请求长度剧烈变化。</p>\n<p>重排周期 $N$ 与预取深度共同决定稳定性。$N$ 太小，重排开销侵占解码步；$N$ 太大，分布漂移后热度表失效，命中率骤降。部署配方给出一个伪代码思路：</p>\n<ul>\n<li>每 $N$ 步收集命中率 $h_l$ 与惩罚计数 $c_{\\text{miss}}$ 的累计值；</li>\n<li>若 $h_l$ 低于阈值且惩罚计数上升，缩短 $N$ 并触发一次全量重排；</li>\n<li>若 SLO 余量低于安全线，冻结预取深度为当前值，不再加深，只允许收缩；</li>\n<li>重排时按 $G_e$ 排序槽位，淘汰 $G_e$ 为负的专家，空出的槽位留给下一周期的高热度候选。</li>\n</ul>\n<p>这套参数的代价体现在尾延迟上：冻结预取深度会牺牲预取收益，已排队 token 的解码步回到按需加载路径，$T_{\\text{miss}}$ 项重新主导 $T_{\\text{step}}$。因此冻结策略必须是渐进的——先冻结深度，再收缩槽位，最后才关闭预取，避免一次性切换造成尾延迟尖峰。这是失败模式里“冻结策略不当放大尾延迟”的直接对策。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-32\">三十二 · 可复现的配置思路：从约束反推参数</h3>\n<p>把上述五节收束成一条可复现的配置流程，顺序是<strong>先定约束，再反推参数</strong>，而不是先选参数再看效果。第一步，测出目标硬件档位上的三个基准量：单层 GEMM 时间随 batch 的变化曲线、HBM 带宽在纯 KV 读取下的可用余量、L2 容量。第二步，由 SLO 的 TPOT 分位数反推允许的 $T_{\\text{miss}}$ 上限，进而由 $G_e$ 判据反推所需的最低命中率 $h_{\\min}$。第三步，由 $h_{\\min}$ 与专家热度分布（预填直方图给出）反推槽位数 $S$，再由 $S$ 与量化格式反推驻留区 HBM 占用，最后校验它与 KV 保底份额之和是否落在 L2 与 HBM 预算内。若校验失败，回退到量化档位或降低 batch 上限，而不是削减 KV 保底。</p>\n<p>第四步，按拓扑档位设定预取深度：域内 NVLink 全连接时深度取 1，跨域时取 2，且第二层只覆盖热度表前若干名专家。第五步，设定 $N$ 的初值为“预填相 chunk 数的整数倍”，使重排与请求批次对齐，减少重排对解码步的干扰。第六步，把四个调度参数与两个配额参数（驻留区 HBM、KV 保底 L2）写入配置文件，并在灰度阶段只调 $\\alpha$ 一个变量，用 TPOT 分位数做二分。这条流程的每一步都有可观测的观测量，不依赖调参直觉。</p>\n<p>最后落到一个工程判断上：这套配置的稳定性上限由路由分布的稳定性决定，而不是由硬件决定。当请求形态从变长对话转向长尾占比高的混合负载时，预填直方图对解码分布的代表性下降，$h_{\\min}$ 无法维持，此时正确的动作是收缩预取深度并把省下的 L2 还给 KV，让系统退回“按需加载 + 分页 KV”的保守形态，而不是加大重排频率去追一个追不上的分布。配置文件的最后一档应当就是这条退路，且它必须能在不重启的情况下被触发。</p>\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-33\">三十三 · 预取带宽账：HBM 与 L2 的双重挤占</h3>\n<p>双相预取在解码步里做的每一笔搬运，都要从同一个 HBM 控制器和同一片 L2 里切走一块预算。设单卡 HBM 有效带宽为 <span class=\"inline-math\">B</span>，解码步中注意力 KV 读取占用比例为 <span class=\"inline-math\">\\(\\rho_{\\text{kv}}\\)</span>，预取流量占用比例为 <span class=\"inline-math\">\\(\\rho_{\\text{pref}}\\)</span>，则留给分组 GEMM 权重读取与激活写回的剩余带宽为 <span class=\"inline-math\">\\(B\\,(1-\\rho_{\\text{kv}}-\\rho_{\\text{pref}})\\)</span>。预取深度 <span class=\"inline-math\">d</span>（每层提前预取的候选专家数）与专家权重字节数 <span class=\"inline-math\">S_e</span> 决定了 <span class=\"inline-math\">\\(\\rho_{\\text{pref}}\\)</span> 的量级：</p>\n<div class=\"formula\">$$\\rho_{\\text{pref}}\\approx\\frac{d\\cdot S_e\\cdot L}{B\\cdot T_{\\text{step}}}$$</div>\n<p>这个式子的含义很直接：预取深度每加一层，就多搬 <span class=\"inline-math\">S_e</span> 字节；而 <span class=\"inline-math\">\\(T_{\\text{step}}\\)</span> 是解码步时长，搬运必须在这个窗口内完成才叫“藏进 GEMM”。一旦 <span class=\"inline-math\">\\(\\rho_{\\text{pref}}\\)</span> 逼近 <span class=\"inline-math\">\\(1-\\rho_{\\text{kv}}\\)</span>，KV 读取就被迫排队，注意力核的 stall 会直接反映到 TPOT 分位数上。工程上判断是否过载，看的是预取队列的未完成字节数是否在 <span class=\"inline-math\">\\(T_{\\text{gemm}}\\)</span> 结束前清零；若连续若干步都清不掉，说明预取深度已经超出带宽预算，此时继续加深只会把长尾从“冷专家加载”搬到“KV 读取”。</p>\n<p>L2 侧是另一本账。驻留专家槽位占用 L2 容量 <span class=\"inline-math\">\\(C_{\\text{res}}=k\\cdot S_e\\)</span>（<span class=\"inline-math\">k</span> 为每层槽位数），而 KV 分页缓存与激活工作集也要 L2。当 <span class=\"inline-math\">\\(C_{\\text{res}}\\)</span> 挤压 KV 的 L2 命中率时，KV 读取会从 L2 命中退化为 HBM 直读，等效带宽需求上升，反过来又加剧 HBM 争用——这是一个正反馈。具体例子：某层专家权重按 NVFP4 压缩后单专家 <span class=\"inline-math\">S_e</span> 较小，槽位数 <span class=\"inline-math\">k</span> 可以设得较大而不爆 L2；但若同一层同时承载长上下文请求，KV 分页块数量随序列长度线性增长，L2 预算被双向拉扯，此时应优先压缩槽位数而不是压缩 KV 块，因为 KV 缺失的代价是每步都付，专家缺失只在路由命中冷专家时付。</p>\n<p>系统代价的量化口径建议固定为三个观测量：预取流量占 HBM 读带宽的比例、驻留区占 L2 的比例、以及解码步中因预取未完成导致的 GEMM 启动延迟。三者任一越界，都应触发预取深度回退，而不是靠调大槽位硬扛。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-34\">三十四 · 命中率衰减曲线：规模上去后先崩的是 h</h3>\n<p>公式 <span class=\"inline-math\">\\(T_{\\text{step}}=\\sum_l\\big(\\max(T^{\\text{gemm}}_l,T^{\\text{pref}}_{l+1})+(1-h_l)T^{\\text{miss}}_l\\big)\\)</span> 里，<span class=\"inline-math\">h_l</span> 是唯一随规模非线性变化的项。批大小 <span class=\"inline-math\">b</span> 增大时，每层被路由到的专家集合 <span class=\"inline-math\">\\(E^{\\text{route}}_l\\)</span> 的基数随 <span class=\"inline-math\">b</span> 增长而扩大，而驻留槽位数 <span class=\"inline-math\">k</span> 受 L2 与 HBM 驻留区容量约束基本固定，于是</p>\n<div class=\"formula\">$$h_l=\\frac{|E^{\\text{hit}}_l|}{|E^{\\text{route}}_l|}\\approx\\frac{k}{|E^{\\text{route}}_l|},\\qquad |E^{\\text{route}}_l|\\propto b^{\\,\\alpha},\\ \\alpha&lt;1$$</div>\n<p><span class=\"inline-math\">\\alpha<1</span> 是因为批量并发下路由有重叠，但重叠不足以抵消基数增长。这意味着 <span class=\"inline-math\">h_l</span> 随 <span class=\"inline-math\">b</span> 单调下降，且下降速度在 <span class=\"inline-math\">b</span> 跨过某个拐点后加快——拐点就是 <span class=\"inline-math\">\\(|E^{\\text{route}}_l|\\)</span> 超过 <span class=\"inline-math\">k</span> 的时刻。规模上去以后，第一个崩的不是 GEMM 算力，也不是 HBM 容量，而是命中率：<span class=\"inline-math\">\\((1-h_l)T^{\\text{miss}}_l\\)</span> 这一项从可忽略变成主导，尾延迟分位数被直接抬升。</p>\n<p>更隐蔽的是热度表的代表性衰减。热度表由预填相路由直方图生成，直方图统计的是该请求（或该批）预填 chunk 内的路由分布。批越大、请求越异构，直方图对解码相下一 token 路由的预测力越弱，<span class=\"inline-math\">p_e</span> 的估计偏差越大，预取收益判据 <span class=\"inline-math\">\\(G_e=p_e T_{\\text{gemm}}-c_{\\text{prefetch}}-(1-p_e)c_{\\text{miss}}\\)</span> 中的 <span class=\"inline-math\">p_e</span> 被高估，导致预取了大量实际不会被路由的专家——这些搬运纯属浪费带宽，还占着槽位把真正需要的专家挤出去。具体例子：一个混合了短问答与长文档摘要的并发批，短问答请求的预填直方图集中在少数通用专家，长文档请求则散布在长尾专家；若热度表按批聚合而不按请求分组，槽位会被通用专家占满，长文档请求的解码步频繁回退按需加载，惩罚计数飙升，重排周期被迫缩短，重排本身又消耗调度器 CPU 时间与一次全量槽位写回。</p>\n<p>工程判断：当 <span class=\"inline-math\">h_l</span> 的滑动平均跌破某阈值且惩罚计数增速超过重排周期能吸收的速率时，应停止加深预取、转而缩小批或按请求分组维护多张热度表。前者牺牲吞吐换尾延迟，后者牺牲槽位复用率换命中率，二者都是规模上限的直接体现。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-35\">三十五 · 通信耦合：预取与 All-to-All 抢同一条链路</h3>\n<p>专家并行部署下，解码步的 token 要经 All-to-All 分发到持有目标专家的设备。双相预取把专家权重提前搬到本地驻留区，减少的是“本地缺失→远端拉取”的路径，但预取流量本身若跨设备（例如驻留区按专家并行分片、预取需从远端 HBM 经 NVLink 拉入），就会与 All-to-All 的分发流量共享 NVLink 5 链路。设单步 All-to-All 分发字节数为 <span class=\"inline-math\">\\(V_{\\text{a2a}}\\)</span>，跨设备预取字节数为 <span class=\"inline-math\">\\(V_{\\text{pref}}\\)</span>，链路有效带宽 <span class=\"inline-math\">\\(B_{\\text{nv}}\\)</span>，则通信侧的可掩盖条件是</p>\n<div class=\"formula\">$$V_{\\text{a2a}}+V_{\\text{pref}}\\ \\le\\ B_{\\text{nv}}\\cdot T_{\\text{gemm}}$$</div>\n<p>注意右侧是 GEMM 时间而非整步时间：All-to-All 与 GEMM 通常在不同流上重叠，预取若也挤进这个窗口，三者争同一条链路，重叠收益被抵消。规模上去后 <span class=\"inline-math\">\\(V_{\\text{a2a}}\\)</span> 随批大小与专家并行度增长，<span class=\"inline-math\">\\(V_{\\text{pref}}\\)</span> 随预取深度增长，两者同时膨胀时链路先饱和，表现为 All-to-All 内核的等待时间被拉长，解码步的通信段成为新的长尾来源。</p>\n<p>一个具体机制上的取舍：把预取目标限定为“本设备已驻留但当前未激活”的专家，即只做 L2 到 SM 的本地提升而不跨设备搬运，可以把 <span class=\"inline-math\">\\(V_{\\text{pref}}\\)</span> 压到零，代价是命中率上限受本地专家分片限制。反之，跨设备预取能提高 <span class=\"inline-math\">h_l</span>，但把通信预算吃进去。工程上应按 <span class=\"inline-math\">\\(V_{\\text{a2a}}\\)</span> 的实测占用动态决定预取是否跨设备：当 All-to-All 已占用链路七成以上时，跨设备预取应整体关闭，只保留本地提升。</p>\n<p>系统代价还体现在功耗上。NVLink 与 HBM 的搬运都是功耗大户，预取错误带来的无效搬运不产生任何有用计算，却实打实地计入功耗预算。在功耗封顶的机柜里，无效预取会挤占本可用于提高时钟或扩大批的功耗余量，形成“越预取越慢”的反常区间——这正是低命中率下整体变慢的物理来源之一。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-36\">三十六 · 尾延迟的三个放大器：回退、重排、冻结</h3>\n<p>尾延迟不是单一来源，双相预取在规模上有三个放大器。第一个是回退惩罚 <span class=\"inline-math\">\\(c_{\\text{miss}}\\)</span>：未命中者走按需加载，其延迟不被任何 GEMM 掩盖，直接落在该 token 的解码步上。批内只要有一个 token 命中冷专家，整个批的步进就被这个 token 拖住（分组 GEMM 需等所有 token 的分组就绪），于是单 token 的回退被放大为整批的尾延迟。设批内 token 数为 <span class=\"inline-math\">b</span>，单 token 冷专家概率 <span class=\"inline-math\">q</span>，则批内至少一个回退的概率为 <span class=\"inline-math\">1-(1-q)^b</span>，随 <span class=\"inline-math\">b</span> 快速趋近 1。这就是为什么大批下 TPOT 的 P99 会被少数冷 token 主导。</p>\n<p>第二个是重排开销。每 <span class=\"inline-math\">N</span> 步按命中率与惩罚计数重排热度表，重排需要读回各槽位的命中统计、重算 <span class=\"inline-math\">p_e</span>、写回槽位映射，这是一次全局同步点。规模上去后重排涉及的槽位数与设备数增加，重排本身可能跨越多个解码步，期间预取按旧表执行，命中率进一步下滑，形成“越不准越频繁重排、越重排越不准”的循环。缓解手段是把重排做成增量式：只对惩罚计数超过阈值的槽位做局部替换，避免全表重写。</p>\n<p>第三个是 SLO 逼近时的冻结策略。冻结预取深度能立刻释放带宽给已排队 token 的解码步，但如果冻结发生在预取队列尚有大量未完成搬运时，这些搬运要么被丢弃（浪费已发生的带宽）、要么继续完成（继续挤占），两种处理都会让冻结瞬间的步进出现抖动。更糟的是冻结只停新预取、不停回退，已排队 token 若恰好路由到未驻留专家，仍要付 <span class=\"inline-math\">\\(c_{\\text{miss}}\\)</span>，尾延迟不降反升。正确的冻结应配合“冻结即提升”：停止新预取的同时，把当前预取队列中已过半的搬运标记为高优先级完成，未过半的直接取消，并把取消的槽位让给已排队 token 的热门专家。</p>\n<p>具体例子：在线对话服务在流量高峰时批大小被迫上调，<span class=\"inline-math\">1-(1-q)^b</span> 迅速接近 1，P99 TPOT 超标触发冻结；若冻结策略只是简单停预取，已排队的长对话请求仍会在冷专家上 stall，SLO 依旧不达标。此时应切换到“按请求分组的小批 + 局部重排”，用吞吐换尾延迟，这是规模上限处唯一稳定的降级路径。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-37\">三十七 · 规模上限的判定顺序与容量规划口径</h3>\n<p>把上述代价按“谁先崩”排序，可以得到一条判定链：先看 <span class=\"inline-math\">\\(\\rho_{\\text{pref}}\\)</span> 是否挤占 KV 带宽（带宽先崩），再看 <span class=\"inline-math\">h_l</span> 是否随批增大跌破阈值（命中率先崩），再看 <span class=\"inline-math\">\\(V_{\\text{a2a}}+V_{\\text{pref}}\\)</span> 是否超链路预算（通信先崩），最后看功耗封顶是否让无效预取挤掉有效计算。四者中任一触发，都意味着当前配置已到规模上限，继续加批或加深预取只会把长尾从一个环节搬到另一个环节。</p>\n<p>容量规划的口径应围绕驻留区做，而不是围绕总算力。给定 L2 预算与 HBM 驻留区预算，可支撑的槽位数 <span class=\"inline-math\">k</span> 与可支撑的批大小 <span class=\"inline-math\">b</span> 之间存在权衡：<span class=\"inline-math\">k</span> 越大 <span class=\"inline-math\">h_l</span> 越高但 L2 越紧，<span class=\"inline-math\">b</span> 越大吞吐越高但 <span class=\"inline-math\">\\(|E^{\\text{route}}_l|\\)</span> 越大。<table class=\"mini\"><thead><tr><th>约束维度</th><th>先崩的信号</th><th>降级动作</th></tr></thead><tbody><tr><td>HBM 带宽</td><td>预取队列在 <span class=\"inline-math\">\\(T_{\\text{gemm}}\\)</span> 内清不掉</td><td>减小预取深度 <span class=\"inline-math\">d</span></td></tr><tr><td>L2 容量</td><td>KV 的 L2 命中率下滑</td><td>压缩槽位数 <span class=\"inline-math\">k</span>，优先保 KV</td></tr><tr><td>命中率</td><td><span class=\"inline-math\">h_l</span> 滑动均值跌破阈值</td><td>按请求分组维护多张热度表</td></tr><tr><td>NVLink</td><td>All-to-All 等待时间拉长</td><td>关闭跨设备预取，只做本地提升</td></tr><tr><td>功耗</td><td>无效搬运占比上升</td><td>提高 <span class=\"inline-math\">G_e</span> 判据阈值，只预取高 <span class=\"inline-math\">p_e</span> 专家</td></tr></tbody></table></p>\n<p>这张表的价值在于把“规模上去哪里先崩”变成可观测的判据，而不是靠经验拍脑袋。每个信号都对应一个具体的计数器：预取队列未完成字节、KV 的 L2 命中率、<span class=\"inline-math\">h_l</span> 滑动均值、All-to-All 内核等待时长、无效预取字节占比。工程上应把这五个计数器纳入推理服务的常规监控，任一越界即触发对应的降级动作，而不是等到 SLO 报警才被动冻结。</p>\n<p>最后落到一个具体机制上：预取收益判据 <span class=\"inline-math\">G_e</span> 中的 <span class=\"inline-math\">\\(c_{\\text{prefetch}}\\)</span> 在规模上去后不再是常数，它随带宽争用程度上升而上升。因此 <span class=\"inline-math\">G_e</span> 的阈值应做成带宽占用的函数——当 <span class=\"inline-math\">\\(\\rho_{\\text{pref}}\\)</span> 接近上限时抬高阈值，只预取 <span class=\"inline-math\">p_e</span> 极高且 <span class=\"inline-math\">S_e</span> 较小的专家；当带宽宽松时降低阈值，用预取换命中率。这个自适应阈值是双相预取在规模上限处维持稳定的关键，也是把“哪里先崩”转化为“哪里先降级”的工程接口。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-38\">三十八 · 预取预算耗尽时，先崩的是 L2 与 HBM 带宽而不是算力</h3>\n<p>把双相预取推到大规模并发，第一个失效点几乎总落在 L2 容量与 HBM 带宽预算上，而不是 tensor core 的算力。设每层驻留槽位数为 <span class=\"inline\">S_l</span>、单专家权重字节数为 <span class=\"inline\">b_e</span>，则驻留区占用为 <span class=\"inline\">\\(M_{\\text{res}}=\\sum_l S_l\\cdot b_e\\)</span>，它与 KV cache 争抢同一块 HBM；同时每步预取搬运量 <span class=\"inline\">\\(B_{\\text{pref}}=\\sum_l \\sum_{e\\in\\mathcal{P}_l} b_e\\)</span> 直接叠加在注意力 KV 读取带宽之上。预取收益判据 <span class=\"inline\">\\(G_e = p_e\\cdot T_{\\text{gemm}} - c_{\\text{prefetch}} - (1-p_e)\\,c_{\\text{miss}}\\)</span> 在单请求下为正，但聚合到批级别后 <span class=\"inline\">\\(c_{\\text{prefetch}}\\)</span> 随并发线性上升，而 <span class=\"inline\">\\(T_{\\text{gemm}}\\)</span> 因分组 GEMM 的批效率提升只亚线性增长——于是存在一个并发拐点，越过它预取就从“藏延迟”变成“抢带宽”。量化到 NVFP4/FP8 能压低 <span class=\"inline\">b_e</span>、把拐点右推，但压缩后的专家仍需解压进 SMEM/TMEM，解压本身也吃带宽，收益不是免费的。</p>\n<p>第二个失效条件是热度表的代表性。热度表由预填相路由直方图生成，其有效性依赖“预填分布可代表解码分布”这一假设；变长对话里用户追问、工具调用回填、系统提示注入都会让解码路由偏离预填统计，命中率 <span class=\"inline\">h_l</span> 骤降。此时每步代价退化为 <span class=\"inline\">\\(T_{\\text{step}}=\\sum_l\\big(\\max(T^{\\text{gemm}}_l, T^{\\text{pref}}_{l+1})+(1-h_l)T^{\\text{miss}}_l\\big)\\)</span>，未命中回退的按需加载重新暴露为长尾 stall，且预取搬运已成沉没成本，整体比纯按需加载更慢。惩罚计数驱动的周期性重排能纠偏，但重排本身要暂停或降级预取、重算热度表，在 SLO 逼近时这段开销直接体现在 TPOT 分位数上。</p>\n<p>尾延迟的放大机制值得单独看：SLO 逼近时冻结预取深度，看似保护已排队 token，实则把冷专家加载全部推回同步路径，长尾请求的 <span class=\"inline\">\\(T^{\\text{miss}}_l\\)</span> 不再被掩盖，P99 TPOT 反而抬升。工程判断是冻结应分级——先冻结低 <span class=\"inline\">G_e</span> 的候选专家，保留高收益槽位的预取，而不是一刀切停摆。规模上限因此由三个预算共同钉死：L2 容量决定 <span class=\"inline\">S_l</span> 上限，HBM 带宽决定 <span class=\"inline\">\\(B_{\\text{pref}}\\)</span> 与 KV 读取的分配比例，功耗墙则限制预取引擎与 GEMM 同时满负荷的持续时长。下表给出各代价随规模变化的定性走向：</p>\n<table class=\"mini\"><thead><tr><th>代价项</th><th>随并发/规模的变化</th><th>先崩的信号</th></tr></thead><tbody><tr><td>L2 驻留区</td><td>槽位数受容量硬限，命中率随批增大而摊薄</td><td>高收益专家被低收益槽位挤出</td></tr><tr><td>HBM 带宽</td><td>预取搬运与 KV 读取线性叠加</td><td>注意力 KV 读取延迟抬升、TPOT 抖动</td></tr><tr><td>All-to-All 通信</td><td>专家并行下预取跨卡，与分组 GEMM 通信争链路</td><td>NVLink 链路排队、解码步同步拉长</td></tr><tr><td>功耗</td><td>预取引擎与 GEMM 并发满载</td><td>时钟回退、持续吞吐下降</td></tr></tbody></table>\n<p>通信维度常被低估：专家并行拓扑下，预取的候选专家若不在本卡，cp.async 只能走本地 HBM，跨卡驻留需借 All-to-All 搬运，与分组 GEMM 的 token 分发争同一条 NVLink 5 链路。规模上去后，预取流量的突发性与 All-to-All 的同步性叠加，解码步的同步等待被拉长，此时即便 <span class=\"inline\">h_l</span> 很高也换不回 TPOT。可行的边界判断是：当预取搬运量与 KV 读取带宽之和逼近 HBM 可持续带宽的某个比例、或跨卡预取占 All-to-All 流量显著份额时，应退回按需加载加静态热点驻留的保守策略，把预取深度作为可调旋钮而非默认开启。</p>\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-39\">三十九 · 精度问题的来源与诊断路径</h3>\n<p>双相预取本身不改数值，但它把专家权重的驻留位置从“按需加载”变成“提前驻留”，于是精度问题的暴露面变了：驻留区里的专家副本可能来自不同量化版本，NVFP4 微缩放量化的 scale 与按需路径读到的权重若不一致，命中路径与回退路径就会算出不同的分组 GEMM 结果。诊断的第一步是把两条路径的输出对齐：在固定输入下分别强制命中与强制回退，逐层比较 logits 偏差；若偏差集中在某几层，说明该层热度表槽位写入的权重版本与按需加载源不一致。第二步查路由直方图的统计口径——预填相按 chunk 切分统计，若 chunk 边界恰好切断了长序列的注意力上下文，直方图会系统性偏向局部模式，导致解码相预取的专家集合与真实路由分布错位，表现为命中率不低但输出质量下降。工程上把“命中率”与“命中后数值一致性”分开监控：前者是性能指标，后者是正确性指标，二者共用热度表却必须独立告警。代价上，强制回退诊断会把解码步的 $T^{\\text{miss}}_l$ 全部暴露，TPOT 短时抬升，因此只在灰度实例上做，不进入生产池。</p>\n<div class=\"formula\">$$G_e = p_e \\cdot T_{\\text{gemm}} - c_{\\text{prefetch}} - (1-p_e)\\,c_{\\text{miss}}$$</div>\n<p>这条判据在精度诊断里的用法是：当某专家的 $G_e$ 长期为负却仍被驻留，说明热度表被旧统计污染，该槽位应优先淘汰并触发重排。举例：某层路由直方图在预填 chunk 切换后突变，$p_e$ 从高位跌落，$G_e$ 转负，但重排周期 $N$ 步未到，该专家继续占用 L2，既挤占 KV 读取又让回退路径频繁触发，两条路径交替出现，数值差异被放大成可观测的抖动。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-40\">四十 · OOM 的三条触发链</h3>\n<p>驻留区与分页 KV 共存于同一 HBM 预算，OOM 不是单一原因，而是三条链叠加。第一条是驻留槽位按批大小静态预留：批大小按显存驻留区容量设定，但预填相 chunk 切分后并发请求数上升，每请求都要一份热度表与槽位映射，元数据随批线性增长。第二条是预取深度在 SLO 宽松时被放大，cp.async 在途数据占用 L2 与 HBM 写缓冲，深度越大在途字节越多，峰值时刻与 KV 分页分配撞车。第三条是重排时的双份驻留：重排热度表需要在新旧槽位间搬运专家，搬运窗口内同一专家存在两份副本。诊断靠三个计数器：驻留槽位占用率、在途预取字节、重排窗口内副本数。任一计数器逼近阈值就触发降级——先冻结预取深度，再压缩批大小，最后回退到纯按需加载。代价是降级顺序错了会放大尾延迟：先压批大小会让已排队 token 的解码步被拆散，TPOT 分位数反而更差，因此冻结预取深度必须是第一动作。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-41\">四十一 · 批抖动与路由不均的耦合</h3>\n<p>批抖动表现为相邻解码步的 TPOT 方差跳变，根因常是路由不均：某几步少数专家吞掉大量 token，分组 GEMM 的负载集中在少数 SM，而其余专家的驻留槽位空转。容量因子路由与令牌丢弃已在别处展开，这里只取它对预取的影响——丢弃改变了实际路由集合，热度表按丢弃前的直方图生成，预取的专家集合与真正参与 GEMM 的集合出现系统性偏差。诊断方法是按步统计每专家的 token 数与命中标记，画二维分布：token 多且命中低的专家是“热而未驻留”，token 少且驻留的是“冷而占位”，前者应提升预取优先级，后者应淘汰。公式上，把 $h_l$ 拆成按专家的命中率 $h_{l,e}$，与 token 占比 $\\omega_{l,e}$ 相乘得到有效覆盖率，覆盖率低说明驻留结构与路由结构错配。系统代价：路由不均时 All-to-All 分组通信量在少数专家上堆积，NVLink 5 带宽被局部打满，解码步的通信与 GEMM 无法重叠，TPOT 尖刺由此产生。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-42\">四十二 · 尾延迟尖刺的定位</h3>\n<p>尾延迟尖刺分两类：预取引发的和回退引发的。预取引发的尖刺特征是尖刺步的预取字节高、命中率正常，但注意力 KV 读取带宽被挤占，表现为尖刺步的 KV 读取时间抬升而 GEMM 时间不变；回退引发的尖刺特征是命中率骤降、惩罚计数跳增，$T^{\\text{miss}}_l$ 直接进入步时间。用步时间公式拆解：</p>\n<div class=\"formula\">$$T_{\\text{step}}=\\sum_{l=1}^{L}\\Big(\\max\\big(T^{\\text{gemm}}_{l},\\ T^{\\text{pref}}_{l+1}\\big)+\\big(1-h_{l}\\big)\\,T^{\\text{miss}}_{l}\\Big),\\quad h_l=\\frac{|E^{\\text{hit}}_l|}{|E^{\\text{route}}_l|}$$</div>\n<p>尖刺步若 $\\max$ 项不变而第二项变大，是回退型；若 $\\max$ 项变大而第二项不变，是预取挤占型。两类尖刺的处理相反：回退型要重排热度表、提升预取深度；预取挤占型要冻结深度、给 KV 读取让路。误判会把尖刺放大——把预取挤占型当成回退型去加深预取，等于在带宽已经饱和时继续加压。具体例子：某解码步命中率从常态跌到低位，惩罚计数在同一 $N$ 步窗口内累积，重排被触发，但重排本身要搬运专家副本，搬运窗口与下一批请求的预填相撞，形成二次尖刺；正确做法是把重排推迟到预填相 chunk 边界，用预填的吞吐余量吸收搬运开销。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-43\">四十三 · 监控指标与回滚闸门</h3>\n<p>监控分三层。第一层是相级：预填相看 chunk 吞吐与直方图统计耗时，解码相看 TPOT 分位数与命中率 $h_l$。第二层是专家级：每专家的 $p_e$、$G_e$、惩罚计数、驻留占用，用于重排决策。第三层是资源级：L2 占用、HBM 带宽分给预取与 KV 读取的比例、在途预取字节。三层指标必须带同一时间戳对齐，否则尖刺归因会错位到相邻步。回滚闸门按代价排序：命中率跌破阈值先冻结预取深度（代价是牺牲预取收益，保住已排队 token 的解码步）；冻结后 TPOT 仍不收敛则回退到纯按需加载（代价是长尾 stall 回归，但数值路径唯一、诊断简单）；最后才是缩批。回滚要保留热度表快照，否则恢复预取时从零重建统计，冷启动期的命中率低谷会被误判为分布漂移。工程判断落在闸门阈值上：阈值应按 TPOT 分位数而非均值设定，均值对尖刺不敏感，用均值做闸门等于放任尾延迟。</p>\n<p>路由分布漂移的监控不能只看命中率绝对值，要看命中率的一阶差分：缓慢下降是分布漂移，骤降是重排或搬运窗口的瞬时污染。前者应缩短重排周期 $N$，后者应把重排移出解码关键路径。长尾请求占比上升时，预填直方图对解码分布的代表性下降，此时热度表应降权跨请求复用部分，改用本请求上一 token 路由做短窗预测，代价是每请求多一份局部统计开销，但避免了全局热度表把长尾请求带偏。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-44\">四十四 · 失败模式与相邻机制的边界</h3>\n<p>把失败模式归成四类便于定责：精度类（双路径数值不一致、直方图口径错位）、容量类（驻留与 KV 争抢、重排双份副本）、调度类（批抖动、路由不均导致的分组 GEMM 负载倾斜）、时延类（预取挤占 KV 带宽、回退惩罚进入步时间）。每类对应一组计数器与一个回滚动作，避免“一出问题就全局回退”的粗放处置。与相邻算法的边界在于：固定缓存策略没有相切分，失败模式只有容量类；纯按需加载没有预取，失败模式只有时延类；本方法把两类失败模式叠加，诊断必须按相分离，否则预填相的直方图开销会被误记到解码相的 TPOT 上。规模上限受 L2 容量与 HBM 带宽预算约束，超过上限后预取收益 $G_e$ 系统性转负，此时继续加深预取只会把失败模式从时延类转成容量类，监控闸门应在上限附近提前动作而不是等 OOM 触发。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-45\">四十五 · 失效边界：预取收益判据、SLO 冻结与回滚闸门</h3>\n<p>这套方案真正的边界不在“能不能预取”，而在“预取是否仍然划算”。用收益判据看单个专家 $e$：</p>\n<div class=\"formula\">$$G_e = p_e \\cdot T_{\\text{gemm}} - c_{\\text{prefetch}} - (1-p_e)\\,c_{\\text{miss}}$$</div>\n<p>其中 $p_e$ 是热度表给出的下一层命中概率，$T_{\\text{gemm}}$ 是当前层 GEMM 可掩盖的时间窗，$c_{\\text{prefetch}}$ 是 cp.async 搬运代价，$c_{\\text{miss}}$ 是未命中回退的惩罚。只有当 $G_e&gt;0$ 时该槽位才值得驻留。命中率 $h_l$ 一旦下滑，$c_{\\text{prefetch}}$ 变成纯沉没成本：搬运占用的 HBM 带宽与 L2 容量直接挤占注意力 KV 读取，解码步的 stall 从“冷专家”转移到“KV 读不到”，TPOT 长尾反而更差。这就是低命中率下整体变慢的机理——不是预取本身慢，而是它抢了注意力的带宽预算。</p>\n<p>三类失败模式要分开诊断，不能混在一个指标里看。<strong>精度问题</strong>：驻留区用 NVFP4/FP8 压缩权重时，预取路径与回退按需加载路径可能走到不同的量化副本，同一 token 在不同步命中不同精度副本，输出出现漂移；诊断手段是给命中/回退两条路径打独立标记，按路径分别统计 logit 偏差，而不是看整体 perplexity。<strong>OOM</strong>：驻留区按批大小与 L2 预算设定，热度表重排若未同步收缩槽位数，会在长尾请求涌入时把驻留区撑爆，表现为分配失败而非算力不足；闸门是重排前先校验槽位上限。<strong>批抖动与路由不均</strong>：热度表依赖路由稳定性，分布漂移时各层 $h_l$ 骤降且层间不均，重排开销本身变成新的尾延迟来源；监控应按层记录 $h_l$ 与惩罚计数，而不是只看全局平均命中率——全局均值会把少数层的塌陷掩盖掉。</p>\n<p>尾延迟尖刺的处置顺序必须是“先冻结、再重排、最后回滚”。SLO 逼近时冻结预取深度，把带宽让给已排队 token 的解码步；但冻结策略不当会放大尾延迟——冻结过晚则预取仍在抢带宽，冻结过深则下一层全部走回退路径，$c_{\\text{miss}}$ 集中爆发。工程判断是：以 TPOT 分位数为触发信号，冻结只降预取深度不降驻留槽位，保证已驻留专家仍可命中。回滚闸门用一张小表约束：</p>\n<table class=\"mini\"><thead><tr><th>信号</th><th>判定</th><th>动作</th></tr></thead><tbody><tr><td>按层 $h_l$ 连续低于阈值</td><td>路由漂移</td><td>缩短重排周期 $N$，收缩低收益槽位</td></tr><tr><td>惩罚计数集中上升</td><td>预取错误</td><td>冻结预取深度，保留驻留槽位</td></tr><tr><td>KV 读取带宽被挤占</td><td>预取过量</td><td>回滚到纯按需加载，热度表只读不写</td></tr><tr><td>两路径 logit 偏差扩大</td><td>精度分叉</td><td>统一量化副本，禁用压缩驻留</td></tr></tbody></table>\n<p>回滚不是关掉整个机制，而是分级降档：先停预取、再停重排、最后退回纯按需加载，每一档都保留热度表作为只读观测。适用边界仍是路由分布相对稳定、预填统计能代表解码分布的场景；长尾请求占比高或分布快速漂移时，$G_e$ 普遍转负，此时正确的工程动作是承认收益收缩，把 L2 与 HBM 带宽还给 KV cache，而不是靠加大预取深度硬扛。</p>\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-46\">四十六 · 同族谱系：四条路线与它们的判据差异</h3>\n<p>把“专家权重怎么进 SM”这件事拆开看，同族算法其实只有四条路线，判据各不相同。第一条是<strong>纯按需加载</strong>：路由到哪个专家就搬哪个，判据是“搬了就用”，代价是冷专家 stall 直接暴露在关键路径上。第二条是<strong>固定缓存策略</strong>（LRU/LFU 一类）：不区分阶段，判据是历史访问频次，问题是预填相的巨大一次性访问会把解码相真正需要的热专家挤出槽位。第三条是<strong>容量因子路由与令牌丢弃</strong>：它改变的是“有多少 token 进专家”，用丢弃换确定性，属于从上游削减负载，而不是改善搬运。第四条就是本方法：<strong>双相切分 + 跨请求热度表复用</strong>，判据是预取收益 $G_e$，用预填相统计出的分布去赌解码相的下一层专家集合。</p>\n<p>这四条路线的关键分野不在“是否预取”，而在<strong>预测信息从哪来</strong>。按需加载没有预测；固定缓存用的是被动历史；容量因子用的是容量上限这一静态先验；只有双相预取把预填相的路由直方图当作显式的、可跨请求复用的预测源。因此选型的第一问不是“命中率能到多少”，而是“我有没有一个可信的、先于解码发生的分布观测”。有，才谈得上预取；没有，预取就是拿 HBM 带宽做无信息赌博。</p>\n<div class=\"formula\">$$G_e = p_e \\cdot T_{\\text{gemm}} - c_{\\text{prefetch}} - (1-p_e)\\,c_{\\text{miss}}$$</div>\n<p>这个判据把选型量化了：只有当热度表给出的 $p_e$ 足够高、且当前层 GEMM 的 $T_{\\text{gemm}}$ 足够长以掩盖 $c_{\\text{prefetch}}$ 时，预取才是正收益。注意 $T_{\\text{gemm}}$ 随批大小上升而上升，所以同一套热度表在小批解码时可能全线负收益，在中等批时转正——这解释了为什么本方法在“变长对话 + 批量并发”的在线服务里成立，而在极低并发或极大批（GEMM 已饱和、带宽已被 KV 吃满）时收益收缩。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-47\">四十七 · 决策表：按场景条件选路线</h3>\n<p>下表把选型条件压成可核对的工程判断。每一行都对应一个可观测的部署特征，而不是抽象偏好。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>场景特征</th><th>首选路线</th><th>关键判据</th><th>主要代价</th></tr>\n</thead>\n<tbody>\n<tr><td>路由分布稳定、预填可代表解码、TPOT 长尾敏感</td><td>双相预取 + 热度表复用</td><td>$G_e&gt;0$ 的专家占比高，$h_l$ 可维持</td><td>预取占用 HBM 带宽与 L2，挤占 KV 读取</td></tr>\n<tr><td>路由快速漂移、长尾请求占比高</td><td>纯按需加载（或浅预取深度）</td><td>热度表重排开销超过命中收益</td><td>冷专家 stall 直接进关键路径</td></tr>\n<tr><td>专家数远超驻留区容量、负载不可预测</td><td>容量因子路由 + 令牌丢弃</td><td>可接受丢弃换确定性时延</td><td>质量损失，且丢弃比例需与 SLO 绑定</td></tr>\n<tr><td>阶段边界模糊（预填解码 piggyback、chunk 极小）</td><td>固定缓存 + 按需回退</td><td>无稳定直方图可统计</td><td>热专家被预填访问冲刷</td></tr>\n<tr><td>分离式部署、预填与解码不同实例</td><td>预取下沉到解码实例本地热度表</td><td>跨实例热度表传递成本可接受</td><td>表同步延迟，跨相复用打折</td></tr>\n</tbody>\n</table>\n<p>读表时要抓住一个不对称：<strong>丢弃类方法削减的是工作量，预取类方法削减的是等待</strong>。前者在带宽受限、专家集合巨大时更稳；后者在带宽有余、GEMM 有可掩盖窗口时更优。两者并不互斥——在专家并行 All-to-All 拓扑下，可以先用容量因子把每卡 token 数压到可控，再在卡内做浅预取，但这时预取的 $T_{\\text{gemm}}$ 已被 All-to-All 等待切碎，$G_e$ 判据要按通信后的实际 GEMM 窗口重算，不能沿用单卡配方。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-48\">四十八 · 命中率阈值：什么时候预取开始亏</h3>\n<p>选型不能只看“有没有预测源”，还要看命中率落在哪个区间。把每步时间写成层求和形式，可以清楚看到预取只在 $h_l$ 高时压缩长尾：</p>\n<div class=\"formula\">$$T_{\\text{step}}=\\sum_{l=1}^{L}\\Big(\\max\\big(T^{\\text{gemm}}_{l},\\ T^{\\text{pref}}_{l+1}\\big)+\\big(1-h_{l}\\big)\\,T^{\\text{miss}}_{l}\\Big),\\quad h_l=\\frac{|E^{\\text{hit}}_l|}{|E^{\\text{route}}_l|}$$</div>\n<p>结构上，预取把 $T^{\\text{pref}}_{l+1}$ 塞进 $\\max$ 里，只要它不超过 $T^{\\text{gemm}}_l$ 就完全免费；真正决定成败的是第二项 $(1-h_l)T^{\\text{miss}}_l$。当 $h_l$ 下滑，这一项线性放大，同时预取本身还在偷带宽，于是出现“越预取越慢”的反转。工程上要设一个可执行的止损点：以惩罚计数为信号，当某层连续 $N$ 步的未命中回退次数超过阈值，就把该层预取深度降一档，而不是等全局命中率崩掉再重排。这与前文“SLO 逼近时冻结预取深度”是同一条控制链的两级——冻结是保底，降档是常态调节。</p>\n<p>具体例子：一个变长对话服务，预填相按 chunk 切分统计直方图，解码相初始预取深度为每层 4 个候选专家。若某层热度表因话题切换失效，惩罚计数在数个解码步内累积，该层回退到按需加载，$T^{\\text{miss}}$ 重新进入关键路径但不再额外偷带宽；其余层继续预取。这种“按层退化”比“整请求退化”更符合长尾分布——尾延迟往往由少数几层贡献，逐层止损能把损伤局部化。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-49\">四十九 · 与分离式专家并行的边界划分</h3>\n<p>同族里最容易混淆的是本方法与分离式专家并行。后者把专家搬到别的卡上，用 All-to-All 换容量；前者把专家搬到更近的存储层级，用预取换等待。判据完全不同：分离式看的是<strong>单卡容量是否装不下专家集合</strong>，双相预取看的是<strong>装得下但加载延迟暴露在关键路径</strong>。若专家集合已超出单卡 HBM，预取无从谈起——没有槽位可驻留，热度表再准也只能预取到 L2，而 L2 容量预算会立刻被击穿。反过来，若专家集合能装下且路由稳定，分离式引入的 All-to-All 通信开销纯属多余。</p>\n<p>混合边界出现在 NVLink 5 域内：当专家集合略超单卡但可落在同域多卡的驻留区时，可以保留双相预取的热度表逻辑，把“预取目标”从本地 HBM 改为域内对端显存，用 NVLink 带宽替代 HBM 带宽支付 $c_{\\text{prefetch}}$。此时 $G_e$ 判据里的 $c_{\\text{prefetch}}$ 要换成跨卡搬运代价，且必须与 All-to-All 调度共享同一份带宽预算——这正是“专家并行 All-to-All 调度”那条路线要处理的冲突，本方法在这里只负责热度表与预取深度，不重复其调度逻辑。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-50\">五十 · 量化与驻留区容量对选型的反向约束</h3>\n<p>选型还被数值精度反向约束。NVFP4/FP8 压缩权重与激活后，单位槽位能驻留的专家数上升，热度表可以覆盖更大的候选集，$h_l$ 的潜在上限提高；但同时预取的字节数下降，$c_{\\text{prefetch}}$ 变小，$G_e$ 更容易为正。这两股力量同向，使量化后的部署更偏向预取路线而非丢弃路线。代价转移到别处：低精度驻留区让 L2 与 HBM 的带宽竞争更集中在 KV 读取上，预取错误挤占注意力 KV 读取的伤害被放大——因为 KV 本身没有压缩到同等程度。</p>\n<p>工程判断因此是：<strong>量化越激进，预取深度越应保守</strong>。一个可执行的配方是把预取深度与驻留区占用率绑定——占用率超过某比例时自动降档，把腾出的 L2 留给 KV。这与前文“批大小按显存驻留区容量与 L2 预算设定”是同一条约束的另一面：批大小决定 $T_{\\text{gemm}}$（进而决定 $G_e$），驻留区占用率决定预取能不能真的藏进去。两者必须联合调，单独调批大小会把预取窗口撑大却把 L2 挤爆，单独调预取深度则会让 GEMM 窗口空转。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-51\">五十一 · 选型落地：三个必须先测的量</h3>\n<p>决策表不能替代实测。落地前必须先在目标负载上测三个量，缺一个就会选错。第一是<strong>预填直方图对解码分布的representativeness</strong>：用预填相统计出的 top-k 专家集合去比对解码相实际路由，算出跨相重叠率；重叠率低则双相预取的前提不成立，应退回按需加载或改用量化压缩驻留区。第二是<strong>每层 $T_{\\text{gemm}}$ 与 $c_{\\text{prefetch}}$ 的比值</strong>：比值小于 1 的层不应预取，直接把这些层从预取计划里剔除，比全局调深度更精细。第三是<strong>惩罚计数的分布形状</strong>：若未命中集中在少数层，逐层止损有效；若均匀散布，说明热度表整体失效，应触发全局重排而非降档。</p>\n<p>这三个量共同决定一个请求该走哪条路线，也决定同一部署内不同请求能否走不同路线——按请求形态分流（长对话走预取、短请求走按需）往往比全局统一策略更省。最终落到具体机制上：热度表不是一次性产物，而是随惩罚计数与命中率周期性重排的活结构；选型的本质，是判断这张表在你的负载上是否值得维护，以及维护它的重排开销是否小于它替你藏起来的那些 stall。</p>\n\n<h3 id=\"alg-moe-prefetch-dual-phase-sec-52\">五十二 · 同族对照：固定驻留、纯按需与双相预取的选型边界</h3>\n<p>把双相预取放进同族算法谱系里，它既不是固定专家驻留（按静态热度把 Top-K 专家常驻显存），也不是纯按需加载（每 token 路由命中即搬）。三者的分野在于「谁承担预测成本」。固定驻留零预测开销但驻留集与真实路由错配时命中率被容量上限锁死；纯按需加载无错配但每次冷专家都暴露完整 HBM→SM 搬运延迟；双相预取把预测成本前移到预填相的直方图统计，用解码步的 GEMM 时间掩盖搬运。选型判据应落在预取收益公式上：<div class=\"formula\">$$G_e = p_e \\cdot T_{\\text{gemm}} - c_{\\text{prefetch}} - (1-p_e)\\,c_{\\text{miss}}$$</div>只有当 $G_e&gt;0$ 的专家槽位数超过 L2 与驻留区预算时，双相方案才比固定驻留更优；若 $p_e$ 长期低于 $c_{\\text{prefetch}}/(T_{\\text{gemm}}+c_{\\text{miss}})$，预取就是净亏损，退化为纯按需反而更稳。</p>\n<p>决策表按三个可观测维度切分，避免凭经验拍板：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>首选</th><th>理由与代价</th></tr></thead><tbody><tr><td>路由分布跨请求稳定、预填 chunk 可代表解码分布</td><td>双相预取 + 跨请求热度表复用</td><td>搬运藏进 $T_{\\text{gemm}}$，TPOT 长尾收敛；代价是预取错误占用 HBM 带宽与 L2，挤占注意力 KV 读取</td></tr><tr><td>专家集小于驻留区容量、路由缓慢变化</td><td>固定驻留</td><td>零预测开销、零回退惩罚；代价是容量一旦不足即硬性 miss</td></tr><tr><td>长尾请求占比高、分布快速漂移</td><td>纯按需加载或浅预取深度</td><td>无错配浪费；代价是冷专家 stall 直接进 TPOT 分位</td></tr><tr><td>SLO 逼近、已排队 token 积压</td><td>冻结预取深度</td><td>保解码步确定性；代价是牺牲预取收益，冻结不当会放大尾延迟</td></tr></tbody></table>\n<p>失效条件要写进容量规划而不是事后告警。第一是路由漂移：热度表由预填直方图生成，一旦解码分布偏离，$h_l$ 骤降使公式中 $(1-p_e)c_{\\text{miss}}$ 项主导，预取从掩盖延迟变成抢占带宽，此时每 $N$ 步的重排开销本身也成为 TPOT 抖动源。第二是带宽争用：预取与 KV 读取共享 HBM，低命中率下预取流量是纯浪费，等于用注意力带宽补贴错误预测。第三是规模上限受 L2 容量与 HBM 带宽预算双重约束，批大小必须按驻留区容量反推而非按算力反推。工程判断是：把 $G_e$ 与实测 $h_l$ 一起做成运行时开关，命中率跌破阈值即降预取深度，而不是等 SLO 违约后被动冻结。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · MoE路由与容量因子</td></tr><tr><td>解决什么</td><td>MoE 解码阶段专家权重按 token 路由动态加载，冷专家触发 HBM→SM 的按需搬运造成长尾 stall；预填阶…</td></tr><tr><td>一句话机制</td><td>把请求生命周期切成预填相与解码相，用上一 token 的路由分布预测下一层专家集合，在计算当前层时异步预取下一层高概率…</td></tr><tr><td>代价与失效</td><td>预取错误会占用 HBM 带宽与 L2 容量，挤占注意力 KV 读取，低命中率时反而变慢；热度表依赖路由稳定性；分布漂移或长尾请求下命中率骤…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-moe-prefetch-dual-phase · 共 8 个片段</p>\n";break;}}})();
